insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "0a435485-c86c-4d17-a835-a4272d68a9ae", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 14, "content": "Cole Heilborn (29:11): I had to go back and double check in my audible library, and I think I'm maybe a quarter of the way through. It's written by this author called David C. Baker, and I think he's kind of a creative thought leader consultant. He's been in that world for a long time now. And guess I'm curious to hear your thoughts thinking about freelancers who are trying to find work, who are simultaneously trying to figure out where do they fit in the industry. I think there's a lot to be said about staking your claim on whatever your ecosystem is. And in doing so, you do position yourself as an expert, whether that's an expert, whether you're just a colorist or whether you are a company that produces rock climbing films. Staking that claim, I think does create a lot of value and I think will help folks find clients or rather help clients find them, because clients want to work with someone who they know can accomplish their specific needs. And if I'm a producer looking for a colorist, I need to find a specific colorist, not someone who's necessarily a jack of all trades. If I'm a client and I'm looking to hire someone who produces rock climbing films, I might look at you guys and be like, oh, these guys, that's what they do, therefore I want to work with them. I dunno, thoughts?", "token_estimate": 326, "speakers": ["Cole Heilborn"], "start_timestamp": "29:11", "end_timestamp": "29:11", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "834554df-e41f-41ee-81f5-78172f5d619d", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 15, "content": "Jon Glassberg (30:26): Yeah, I mean, the outdoor industry is not like Hollywood is with mentorship and with understudies and with the kind of ranking and pecking order that kind of helps you guide your way through the industry. If you're interested in, I don't know, being a film director, you're definitely going to start out assisting and shadowing and just getting involved in film production. And the same goes for the outdoor space, but it doesn't have as much structure. I mean, you have to go out and assist as a new photographer or filmmaker, and you have to see how the sausage is made from the bottom of the barrel, really. I mean, you have to understand how things are happening and working before you can jump in and start telling people what to do. So I think that goes back to paying your dues, and I think that's super important. (31:24): But yeah, you really need to learn that process before you can dive in completely and just be willing to take the low paying jobs or the non-paying jobs and build relationships with people and get familiar with your scene. I'm in Colorado, so I mean, if you're in Denver, let's say, and you want to get involved in film production, you need to be out assisting and getting involved in productions, whether it's pre-production or production or post-production, any way you can to see different pieces of the puzzle. But then also, I remember when I was starting, I learned a bunch of stuff that I really wished that had been taught to me earlier. I remember I did a bunch of videos on how to shoot a photo and video from a rope, basically how to jug a rope, how to get in position on a wall and get above a climber and stabilize yourself enough to take video. (32:25): And I always thought back then, in the early two thousands, 2000 tens, we were just trying to share our experience and share our knowledge in the outdoor space so that we could educate people even if they never even use it. People just liked seeing how to jug a rope and get in position to shoot because it was interesting and it was like a niche that had never really been shown. The behind the scenes of stuff used to be crazy Hollywood productions where, I don't know, some French TV channel was shooting Lin Hill on the nose or something with crazy rigging and all this insane stuff. So for us to be nimble and fast and be able to jug a rope and get in position in five minutes and document somebody climbing was totally mind boggling to people back then. So I just made a bunch of how-to videos back in the day and talked about how my process worked and maybe mentored some people inadvertently through some videos. (33:22): But I mean, I think putting out information as an expert, like you're saying, is super valuable. People want to learn really badly, and I mean, that's funny. Like why I, I've been involved in this Crux Academy project was it's basically just education about all kinds of different topics in the outdoors. It might be as simple as how to boulder with Nina Williams or whatever, or it could be more in-depth topics. So I think people are really hungry to learn, and especially if there's no traditional way to go through a mentorship or an internship or go through that process, then you need to at least be watching things online and using resources to understand more because that is really how it goes down in the real world.", "token_estimate": 845, "speakers": ["Jon Glassberg"], "start_timestamp": "30:26", "end_timestamp": "30:26", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "753f096d-0e7a-4822-baf7-5aa10b240a37", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 16, "content": "Cole Heilborn (34:11): So I've heard this before and I have thought this many times, that if you niche yourself too much, then you become pigeonholed and you can't break out of that spot that you have dug yourself into. I guess I'm curious to hear your thoughts on that. Is pigeonholing bad? I know for a lot of people who are just starting out, they're like, if I pigeonhole myself so early, I can't find enough work just to support myself, so I have to spread myself thin, take everything that I can. And so I realized there's the element of time here, which plays a big role in, I think this question, but I don't know you, I mean, have you pigeonholed yourself? Do you feel like you're stuck?", "token_estimate": 174, "speakers": ["Cole Heilborn"], "start_timestamp": "34:11", "end_timestamp": "34:11", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "dea11bb7-ea68-41c2-9ffa-0766f2b51536", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 17, "content": "Jon Glassberg (34:51): I mean, yeah, sometimes I feel like I would maybe get jobs as a DP outside the outdoor industry, but because what I do is so specific to climbing adventure and outdoor stuff that I just don't get the job because they think that that's what I'm capable of. But I mean, it's interesting. I think if you're pigeonholing yourself, you're really becoming an expert at one specific thing. And I mean, I just think about when I hire a sound guy for location work, he's usually a 50 to 60-year-old guy who is really, really good at sound and I hire him because he is going to for sure, and he is going to be awesome at it, but he's also probably not doing a lot of other stuff in production. He is just doing sound work and he's probably not getting a ton of jobs. He's just doing, whenever someone calls, he is ready to go and he is got his kit and he will nail it for sure, but he's an expert and he's pigeonholed a little bit. (35:55): I mean, I think as you get more exposure and as you create more stuff and you just get bigger, your business grows, you will probably start to refine more and more. It would be my guess as as you're freelancing and you're taking any job here and there, you're also working for jobs that aren't paying as much and those jobs don't have as high of expectations of you. And if you're getting 150 bucks to go do sound for a day, no one's expecting you to deliver Hollywood sound all day every day and mix this crazy thing. But you'll learn a lot and you might be able to start to dial in what you love and what you're passionate about, and then that's what you start to seek out more. But yeah, I think you just kind of over time you get more refined.\n\nCole Heilborn (36:47): So for folks who are just starting out, how important is having a niche or is that something that folks should even be considering? Should they just be focusing on trying things out, feeling out what they like and as they do so they slowly start to become more focused in terms of what they start to call themselves?", "token_estimate": 511, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "34:51", "end_timestamp": "36:47", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "cec9bc03-0a1a-42a6-8ea3-eaae6ea42af3", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 18, "content": "Jon Glassberg (37:07): I think feeling out what you like is super important because you need to identify what you're interested in. I mean, if you're getting into this world, you're probably someone that is pretty self-motivated and you're interested in creating something artistic and fun and exciting, and if you spend your first few years dabbling in all the different types of production and you realize that you're a really good storyteller and maybe you're most motivated as an editor because you get to tell the final story and really tweak and dial in how that story is told, maybe that's what gets you psyched. I mean, ultimately, yeah, any of us could probably buckle down and be one of the different roles in the outdoor industry film world, but if you don't love it, then it's going to be a long career of just going through the paces. So I mean, you're better off finding something that you're actually passionate about, and if you have a niche of any kind, definitely embrace it your foot in the door to at least start to understand if you like something or not. (38:17): And maybe that foot in the door just by being a rock climber gets you involved in rock climbing productions and maybe you realize that you want to get in a narrative film or something like that, totally separate from rock climbing, but you at least got a taste of what it was like to do a production and you kind of see the path from there. I mean, I think any niche just acts as a door opener and as a way to network and a way to just communicate with your scene. And I mean, I've had friends that were passionate rock climbers that were good at video and decided that they wanted to just get into music and shoot music. It was a similar style of shooting competitions. It was kind of like going to a concert and shooting a DJ or shooting a band or whatever. They just found something that was loosely associated to what they originally got their foot in the door with. They honed their skills as filmmakers and then they're like, oh, actually I think music is the next avenue. I'm going to follow that path. I mean, I think you just kind of go with what feels natural and what motivates you because in a creative space, if you're not motivated, it doesn't make sense, I don't think.", "token_estimate": 568, "speakers": ["Jon Glassberg"], "start_timestamp": "37:07", "end_timestamp": "37:07", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "02e54d0e-f6e3-4966-b99c-dfd9eaa89752", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 19, "content": "Cole Heilborn (39:26): So you can pigeonhole yourself, but what I'm hearing is that you can also change your focus if you want to.\n\nJon Glassberg (39:36): Yeah, I mean you could be pigeonholed as an editor, but you might not always be editing documentary film or commercials or brand pieces or whatever it might be. You could definitely find editing work that's inspiring in a lot of different places in the film world. I mean the same would go for any individual job within that space, or maybe eventually you become a director or something and you just continue to level up. I mean, basically the idea of just honing your skills is always going to be good. I mean, there's nothing wrong with that in my opinion. I mean, pigeonholing yourself when you're really early on and you don't know what direction to go in, yeah, that's bad. But if you have a sense of what you like and what's interesting and inspiring to you, I think you should totally follow it.\n\nCole Heilborn (40:26): So let's say I'm a freelancer 10 years into doing this and I don't have a niche. Do you have to have a niche to live to have a good living, to do good work? Can you be a jack of all trades and still succeed?", "token_estimate": 298, "speakers": ["Cole Heilborn", "Jon Glassberg"], "start_timestamp": "39:26", "end_timestamp": "40:26", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "1cbb0ca3-a70b-4d1f-98f1-fec52d81d4e4", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 20, "content": "Jon Glassberg (40:44): Yeah, I think so. That's more rare, I would imagine, to be really successful and to be good at everything. I mean, that's the dream. I mean, I don't know. I think you could be pretty damn good at a lot of things, but to be truly amazing at one thing is super rare as well. So I mean, I think you find what you're good at. You kind of define yourself by what you're most interested in and what you can actually execute on. I mean, you can fake it until you make it only so far. Eventually you're going to have to make something or do something that you may or may not be an expert in. And I mean, I think that's quite challenging when you get to that level where people are paying you a lot of money to do something and you might not be the best at it. That's something you want to avoid unless you can really put it up and do it. I think that's stressful to me is hiring people sometimes not knowing their skill level, but just assuming that they have some basic level and relying on them to be very, very good at their jobs, especially in the creative space is hard.\n\nCole Heilborn (41:57): So we've kind of been discussing this topic specifically in regards to a freelancer. I'm curious just to kind of look at it from a different perspective. So you're in an interesting position where you are simultaneously a freelancer. John gets hired for jobs, but louder than 11 also gets hired for jobs and you run and manage that. How from a company perspective, is this conversation different in regards to niching and finding that focus? You are the company, but you're different, but you're the same, right?", "token_estimate": 407, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "40:44", "end_timestamp": "41:57", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "3eb6ced1-0a1f-474c-967e-22435f86a3cd", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 21, "content": "Jon Glassberg (42:31): Yeah, different but definitely the same. I mean, if someone's hiring louder than 11 to do a production, they're hiring John Glassberg as the person to put the production together and to see it from start to finish. I mean, most clients wouldn't care if some of the smaller roles were filled by anyone that could help deliver a final product that they're happy with. But I think that from a director's perspective, you're you're trying to have your finger on the whole process to make sure that you're guiding it for the client to have the confidence in you to achieve it. I mean, if ladder 11 was hired as a production company and they weren't interested in me as the person guiding it, that would be pretty weird, and I would feel like if something went out the door that someone else worked on it, I never saw it. (43:25): That would be weird as well. So you're really, I mean, as a director, I'm involved in everything that we do, even if, I mean it's only me and my wife as full-time employees here and everybody else that we work with is subcontracted, but that's just because one, we don't have the volume that we're overwhelmed that we need to hire a full-time extra staff people or extra staff people to work in. But most of the time we're just flexing up and down for productions. Most companies are, and we just hire individually for the job. So very rarely. I mean, I've had full-time employees in the past, but I don't know that that's necessarily the way forward. I'm still experimenting with it and still learning what's good and bad with having employees and what that means, but that's actually really interesting to me as a business owner is all the really tedious business things that you have to deal with unemployment and health insurance and taxes and tax rates and all the crazy stuff that you just have no idea what to do with when you first get started. (44:39): But that over time you start to learn is super valuable to know. And then being able to serialize that across multiple businesses and use that expertise to quickly develop and run other companies is super awesome. I mean, that's something I was super lucky and fortunate enough to go to grad school and focus on business for that specific reason. I was like, I don't know anything about anything other than climbing and print and graphic design. I need to know how to run a business if that's what I want to do. So I just focused on learning how to do the basics in business and honestly, they could teach you all stuff, all that stuff in business school, but once you actually go and start applying it to a real business that's yours, that actually matters, that'll make or break your financial success is totally different game. So it really changes. I mean, if you're good at QuickBooks and you're organized and you can dial that business side of things in, it just makes your whole life so much easier and you don't run the risk of potentially just imploding and not being able to handle it or burning out and spending all your time trying to punch numbers into a spreadsheet.", "token_estimate": 773, "speakers": ["Jon Glassberg"], "start_timestamp": "42:31", "end_timestamp": "42:31", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "dbe18ba8-a85e-4408-bf40-7e56addc88c4", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 22, "content": "Cole Heilborn (45:52): Yeah, I've spent a few hours in my life researching how to use QuickBooks and I don't enjoy it.\n\nJon Glassberg (46:01): No, and eventually, I mean, eventually you hire someone to do your books and then do your taxes and all that stuff, which is great, but I definitely did not have a bookkeeper or a tax person when I was 25 and making films. So that is a great hire. There is no need for any director or business manager to ever need to know the ins and outs of balancing your books.\n\nCole Heilborn (46:26): And it's probably best that you don't either, because you might really screw up and put yourself in a deep, deep hole that you can't get out of\n\nJon Glassberg (46:33): Or just commit involuntary tax fraud.\n\nCole Heilborn (46:36): There's that. Also, I don't think the IR RSS doesn't care if you don't know what the rules are, they'll slap you with a fine and send you a few letters.\n\nJon Glassberg (46:46): Yeah, they're coming for you.\n\nCole Heilborn (46:48): Well, John, we've chatted about a variety of different things in our time today. I'm curious, we're kind of coming up against the end of the clock, but over the last few years, many years as you've been doing this, I don't know, what were some things that you've learned that you wish you knew when you started that you would want to impart on folks who are just embarking down this journey of trying to figure out where do they fit in? How do they fit into this space?", "token_estimate": 366, "speakers": ["Cole Heilborn", "Jon Glassberg"], "start_timestamp": "45:52", "end_timestamp": "46:48", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "290dd336-5ed3-4923-a6b6-a8e091ab2712", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 23, "content": "Jon Glassberg (47:17): I mean, I think the two biggest things are paying your dues, creating content all the time. If that's the space you want to be in and you really want to make visual for a community like the outdoor space, then you need to be making stuff all the time at all costs, no matter what. You need to be pumping out photo and video content if that's your thing. If you're a writer, you need to be writing all the time. If you're an editor, you're editing all the time. If you're into film and photo, you need to be creating that stuff all day every day, even if it's bad, you're honing your skills, you're getting better, people are seeing you do it. The exposure you get from making anything is going to get to be crazy. Advertising for your brand as an individual and as a director or as a filmmaker or photographer. (48:09): I mean paying your dues. That's the number one thing in my opinion. And the second thing that I think goes a really long way is networking. I mean everybody, I think that's a buzzword that people love to use, but it is a buzzword for a reason, because it totally works. If people are talking about you and they know who you are and they're used to seeing you and you're going to events and you're attending trade shows and you're at competitions and you're in the outdoor space all day every day and you're connected with people and you're palatable in some basic fashion and people can be around you and are cool talking to you, then that is going to go a very long way. People just like to feel like they have a connection to the individual that's doing the work. It just goes so far.\n\nCole Heilborn (48:57): Yeah, you had to, I dunno, if you had to sum up any lasting thoughts about finding your focus, finding your expertise, for our folks listening, is there anything that we didn't cover that you want to make mention of?", "token_estimate": 468, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "47:17", "end_timestamp": "48:57", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "32972075-675e-4ae5-9609-17b126bed045", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 24, "content": "Jon Glassberg (49:11): No, I don't think so. I mean, I think identifying your niche is hard. Who knows? There are plenty of people out there that didn't have what I went through as a kid, really. I mean, I just knew right away that I loved climbing, and if you can identify anything in your life that you're obsessed with to the point where you're willing to make $0 creating around that idea and concept for as long as it takes to make it, then that's how you're willing to put in the time. I mean, I was willing to do whatever it took to make it in this industry and to see my passion become my actual day to day. And of course, that will change as you do it more and you get more refined or whatever it might be, and you might do some stuff you don't love, but ultimately, if there's something that you love at the core of what you're doing, then I think it is going to be something that you're going to be willing to put all of your time and energy into without hesitating.\n\nCole Heilborn (50:20): Yeah, well said. I guess one question that you just made me think of for you, rock climbing is such a big part of your life and it's obviously bled into your professional career. For folks who aren't a professional athlete and they don't have that way to help define their career or focus their career, I mean, do you need that component in order to find your niche as a creative? What are other ways that you can work around that? If I'm not you?", "token_estimate": 363, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "49:11", "end_timestamp": "50:20", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "ed2cb298-3de4-4c47-b1b2-04b34381b9b8", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 25, "content": "Jon Glassberg (50:48): Yeah, I mean, I think you need to identify what you're good at. And it might not be necessarily a hard skill like climbing or surfing or mountain biking or whatever it might be in the sports world, but identify what you're good at. If you're really good at networking and talking to people and you want to be in the outdoor space, there is a place for you there. If you're really good at business and you're really dialed in on running a business and that's what you want to do, there's definitely a place if you're, you're loosely associated with something that you like somehow down the road, I think you're doing yourself a favor. You might not be a professional climber, but you might go to the climbing gym a little bit and you might like the community and the people that you interact with at the climbing gym and outside, and you might be really good at sound, who knows? And you want to get into that, and that's your way in. I think just identifying what you're good at or what your skill sets are, just on a fundamental level, will help you refine what you might be good at in the outdoor space, for example.\n\nCole Heilborn (51:58): And I think the beauty of having expertise as an individual, and hopefully with other folks having expertise as well, you can as a freelancer, as an individual whose help you need for particular projects. So let's say I'm shooting something and I need help with rock climbing, maybe that's not my thing, but it's your thing. And so I can call you up and say, Hey, I know you're really good at this. I'm good at whatever I'm doing in this project. Maybe I'm producing, let's work together on this. So I think being an expert signals to your peers as well, how we can collaborate together.", "token_estimate": 439, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "50:48", "end_timestamp": "51:58", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "589e1a6a-c5df-4f27-af05-19c56f26f729", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 26, "content": "Jon Glassberg (52:37): And maybe you're just good at being flexible too. I think I've watched people come into the outdoor space as models. They're just good looking people that are hired to be models, and then they become assistants for photo shoots, and then from there they become stylists, and then from there they become, they own stylist companies. And I mean, there's so many ways that you can just pick a path and just see what happens, and just do the best you can in that space and just see if it makes space for new work within that realm that you can level up to. I think you got to have a little bit of patience, and I think especially in the outdoor industry, you can't really fake it until you make it. People see through the BS really fast in this world. Maybe you can do that in other industries, but you definitely can't do that in the outdoor space. If you show up into the climbing world and you start pretending like you're something that you're not, people will call you out and you just won't make it. I mean, yeah, it's just as simple as that. I think that as you get more refined, you'll also realize that it's more valuable to not fake it because you're going to have to eventually do the work, and you're going to have to eventually put your money where your mouth is.\n\nCole Heilborn (53:56): Yeah. Yeah. Well said. Well, John, I want to thank you for taking the time. This was a lot of fun, and I think this conversation will definitely resonate with folks as part of this month of content focus towards freelancers. If people want to learn more about you, any of the companies you're affiliated with, where can people go to connect?", "token_estimate": 416, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "52:37", "end_timestamp": "53:56", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "d3cb247e-abd4-4f2f-aeb6-b6954bda58ca", "episode_id": "ffbbb1e5-59f1-4a24-84d5-2d9d6d31b3e1", "cms_item_id": "68225dfc7bb476527f8c4886", "chunk_index": 27, "content": "Jon Glassberg (54:16): Yeah, I mean, most of my stuff is on Instagram. My Instagram is just my name, John Glassberg, but all of our commercial and documentary work is on louder than 11, so l t1.com. And then I also, like I said, own, or I'm co-founder of Crux Academy, so anything that you want to learn in the outdoor space, that's another great place to go check out some of our work, where a lot than 11 is the production partner at Crux Academy. So anything that you see there, we're producing. And yeah, I mean, I just try to have a big online presence so people know who I am and where I'm at. So that's where you can find me.\n\nCole Heilborn (54:54): Beautiful. Well, John, thanks again. Have a great rest of your week and have fun with whatever you're working on. Is there anything we should be on the lookout in the horizon for projects coming out?\n\nJon Glassberg (55:06): Well, we have a ton of little brand pieces that we're working on for all the different companies that we do work for in the outdoor industry, but I'm working on a feature documentary film right now, which is going to be really, really exciting. I can't really talk a ton about it yet. I don't know what is exactly going to materialize, but I've not done a feature doc before, so this will be a big deal and a big deal for me, and hopefully it's good and people like it. But yeah, that's going to be my focus for the year.\n\nCole Heilborn (55:38): Nice. Awesome, man. Well, we'll have to keep a lookout for that. And yeah, keep us posted when that comes out.\n\nJon Glassberg (55:44): Thanks. Will do. I appreciate being on the podcast. It was super fun.\n\nCole Heilborn (55:47): Absolutely. Alright, John, take care.\n\nJon Glassberg (55:49): Thanks.\n\nCole Heilborn (55:51): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 490, "speakers": ["Jon Glassberg", "Cole Heilborn"], "start_timestamp": "54:16", "end_timestamp": "55:51", "podcast_index": 94, "episode_name": "Ep 94: Finding Your Focus As A Freelancer | Jon Glassberg | Louder Than 11", "slug": "ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "web_url": "https://www.portsidepro.com/podcast-feed/ep-94-finding-your-focus-as-a-freelancer-jon-glassberg-louder-than-11", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:116"}, {"id": "6fc462eb-12e3-449a-8461-195e90fa9b85", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 0, "content": "Justine Mulliez (00:00:02): As freelancers, as contract workers, we're always having to have money negotiations with our clients. So you're having to go to bat all the time, and it's just you. It's not like you have an agent selling your work and you're the artist, right? And you're having to be courageous in the work you create and then courageous and selling the work that you create. You also don't know what other people are charging, so there is this constant fear around, well, if I price myself too high, someone's going to come in below me.\n\nCole Heilborn (00:00:30): Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer, I hope you enjoy today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Sided Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Back Country Marketing Podcast. My name is Cole Hoborne. Today I'm sitting down with Justine Mollier. She's a business coach at just a wild thought coaching. She works with creatives, freelancers, and entrepreneurs in the outdoor industry to help them pretty much solve any problem that they seem to have. Justine, how are you?\n\nJustine Mulliez (00:01:19): I'm great. What a wonderful intro. I love helping people solve their problems. Yay.\n\nCole Heilborn (00:01:25): And I might've been a little vague there about solving anything, but Well, I feel like you kind of have that reputation. I've had the opportunity to work with you and I know other people have as well, friends of mine and just other colleagues in the outdoor industry, and you seem to help a lot of people.", "token_estimate": 484, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:00:02", "end_timestamp": "00:01:25", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "131c1d02-7bfe-4d69-afc9-341ffcdc4989", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 1, "content": "Justine Mulliez (00:01:43): Thanks. Well, I think what's wonderful is that I get to help people help themselves, and I think that's a very good perspective to look at when I think about coaching is like I'm not here to drag somebody to a solution, whereas I'm really here coaxing somebody to figure out what the solution looks like for themselves. So yeah, that's definitely the lens through which I look at coaching, but it's always wonderful to hear that the work that I do gets to be impactful and help people help themselves.\n\nCole Heilborn (00:02:15): Well said. Well, as folks know, we're in the middle of our March freelancer content episode month, whatever you want to call it. I don't think we have an official name for it\n\nJustine Mulliez (00:02:26): Yet. The extravaganza.\n\nCole Heilborn (00:02:27): The Extravaganza. And so I'm excited to continue this conversation with you, Justine. We've got a really fun in-depth and hopefully really insightful conversation ahead of us For all the freelancers or folks who are just tuning in, who aren't a freelancer, who are interested, we're going to be talking all about money and all of the different facets and different ideas around money and how it relates to our lives as freelancers in the industry. Before we go there, Justine, I'd love if you could give us a quick introduction, a quick little background on yourself for folks who don't know. Justine was on the podcast, I think on episode 54 or 53, so if you're looking for a little extra content to listen to this week, I highly recommend going back and checking out that episode. But for folks who don't know, Justine, tell us a little bit about yourself.", "token_estimate": 418, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:01:43", "end_timestamp": "00:02:27", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "c69c287e-265c-4779-8107-1a521e275164", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 2, "content": "Justine Mulliez (00:03:17): So I am a certified professional proactive coach, and I work specifically with freelancers, creatives, entrepreneurs, and adventurous people in the outdoors industry. And really what that means is that I get to work with individuals who are either in the beginning stages or in the perfecting stages of their business or their freelance career or their career, and I work with people to really build a life that honors what's most important to 'em and that ultimately looks like them. I kind of couple my seven year experience as a freelancer in the action sports industry in Europe with my training to really help people basically not make the same mistakes that I made, and especially when it comes to money, make way more money than I ever did. And I really see, as we were talking about earlier on, is I really see my role as just basically their partner in that adventure and walking alongside somebody and pointing things out and getting curious and making sure that over time a person gets to just be exactly who they are and that they have all the tools that they need to make their own decisions and to live a life that's fulfilling and aligned with what's important to 'em.", "token_estimate": 303, "speakers": ["Justine Mulliez"], "start_timestamp": "00:03:17", "end_timestamp": "00:03:17", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "8fe2d4d7-fb13-4823-8c93-5aa5a1379b4f", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 3, "content": "Cole Heilborn (00:04:27): It is interesting, we were talking about this just before we started to record the differences between the idea of coaching and improvement based on cultures and thinking about what my perception of coaching was prior to working with you. It seems to kind of have a negative connotation or a can, at least that was my imagination behind it. It seems like this, what's wrong with me? Why do I need someone to help me? But I think for anyone who is a creative, a freelancer or an entrepreneur or just anyone, I think you find yourself in situations, whether it's work or life, oftentimes they're tangled and there's a lot of things that you have to figure out oftentimes by yourself. And I think having someone like yourself who can help you navigate those scenarios and help you look at a perspective from an outside perspective, but really it's yourself, your own perspective, I think is extremely helpful and has been a really cool experience. So I guess what I'm saying is I think that's why I'm really excited to have you on the show today because I think there's just the idea of improving. I think while it seems kind of gross, I think it's awesome. I think it's a lot of fun, and I think this idea of money and how we view money is a really complicated scenario, a really complicated idea, and there's a lot of misconceptions and stereotypes around money, and hopefully we can kind of dive into some of those and break some of those down.", "token_estimate": 368, "speakers": ["Cole Heilborn"], "start_timestamp": "00:04:27", "end_timestamp": "00:04:27", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "e622eca4-4d54-4b17-96b2-9cd67cb8dc86", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 4, "content": "Justine Mulliez (00:05:54): Yeah, totally. And I love that you brought that up totally. I mean, yeah, coaching is a really predatory industry sometimes, and I think it's really important to highlight that no one's broken, and I really don't see my role as fixing someone. If anything, that's what I had to hardwire in my brain because a natural fixer, and I'm like, let me help you. When really it's like, hold on, I'm disempowering you by trying to get involved and how can I help you? As you were saying, look at things through a different perspective and zoom in and zoom out accordingly. And really on the topic of money in particular, so much of our relationship to money is unexamined, and we make a lot of decisions around our belief systems, around the stories that we tell ourselves. And so sometimes it just helps to have somebody come in with a magnifying glass or a crazy lens and be like, Hey, what if we looked at this topic through this lens? What would be possible there? What options do we have? What choices could we make? And so that's why the foundation of the money conversation being narratives, I'm really excited to get into.\n\nCole Heilborn (00:06:59): So let's dive in. I guess why is money such a hot topic for everyone, for freelancers?\n\nJustine Mulliez (00:07:07): Yeah, I mean, I think first and foremost, I think money is something that we, it's not a class in school, for example. So there's not a curriculum around money. There isn't a specific education that people are like, great, this is the best way of teaching people around money, no money lessons. You learn that from whether or not your parents are yelling at each other over money. You learn about the relationship that money has with status. You learn about that with access and credit score and whether or not your parents can get approved for a credit card. So a lot of what we learn around money is it's misconstrued and it's also just stories. It's experience, it's experiences that really dictate how money makes you feel and therefore how you feel with money. I think that's why it's so complex is because we're not taught specifics. We're just absorbing constantly.", "token_estimate": 542, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:05:54", "end_timestamp": "00:07:07", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "b401b537-bdae-487a-8c8c-36ce6aaae027", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 5, "content": "Cole Heilborn (00:07:58): So when we first chatted, we talked a little bit about this idea of our mindset or our stories that we hold about money. And I never really thought about it that way until our conversation, and I guess I'll use myself as an example. So growing up, I spent a lot of time with my grandparents, and every time we would go out to dinner, which wasn't often, they would always use a coupon. And so as I've grown up and become an adult, I've always believed that if you're going to go out to dinner, you have to use a coupon, otherwise you can't go out to dinner. And that seems like a really kind of silly example, but as I've become an adult, I have learned to be able to go out to dinner without using a coupon. But that small example or that precedent that was set by someone earlier in my life had a big impact on how I engaged with restaurants as an adult. And I think about, that's such a small example, but there's so many big examples about how we view money and how that affects our decision making skills.", "token_estimate": 259, "speakers": ["Cole Heilborn"], "start_timestamp": "00:07:58", "end_timestamp": "00:07:58", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "240ab734-7bff-4cd2-ba75-f285015607d0", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 6, "content": "Justine Mulliez (00:08:53): Totally. I think that's what a specific example, and we could even spend time thinking about what that means about maybe what you equate with the food and beverage industry or because all of it does, I kind of look at it almost as a vein system where those tributaries of impact at Resound in different parts of our lives, obviously we're whole people, it sinks in. I mean, very similarly. I grew up in an environment where I think we were fairly comfortable. My dad is an entrepreneur that has always worked out fairly well for him. And I have been keeping my books since I was probably seven years old. I would get $7 of pocket money a month and I had to show my expenses and where I was spending it. And so I've been keeping my books since I was a child because yes, we were comfortable, and I think for my dad, it was really important for him to teach us that you have to track money. (00:09:50): And simultaneously, I was told something along the lines of money that's not invested or in a business or basically money spent is bad and that you should be investing your money or saving your money. So it's just like all of these things. I'm just kind of also seeing, it's like a pack of cards and each card is a different notion that you have around money. And when you look at your cards, you're like, oh, a lot of this is contradictory, and I pick and choose when something is convenient for me to apply. And that's again why money is so complicated\n\nCole Heilborn (00:10:23): As a coach. What are some of the common narratives that you come across as you work with freelancers that they hold about the idea of money?", "token_estimate": 413, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:08:53", "end_timestamp": "00:10:23", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "d7e8acde-f035-45f1-9a7f-c0358f807073", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 7, "content": "Justine Mulliez (00:10:31): So the number one is I'm not worth getting paid. The other one that's quite common is that money is bad. So the source of money equals capitalism and capitalism equals oppression, and therefore money is bad. Some has to do with, I came from a privileged background, I don't need to get paid all that much or that it's bad to ask for a lot of money, but really it's just this kind of resounding notion that almost like I'm ripping somebody off by asking to get paid. And so that's where that either imposter syndrome or inner critic work is combined with money stories. Because if you don't think that the work that you're doing has a purpose or is powerful, then you are way less likely to ask to get paid for it.\n\nCole Heilborn (00:11:21): Interesting. And why are those kind of common narratives, why does that create a challenge for freelancers? I guess? What is the overall problem that freelancers often face in this industry?\n\nJustine Mulliez (00:11:35): I mean, you're repeatedly asking to get paid. So as freelancers, as contract workers, we're always having to have money negotiations with our clients. And so you're having to go to bat all the time, and it's just you. It's not like you have an agent selling your work, you're the artist. So you're both having to, and I think we talked about this last time, you're having to be courageous in the work you create and then courageous in selling the work that you create. So you're constantly having to advocate for yourself. You also don't know what other people are charging. So there is this constant fear around, well, if I price myself too high, someone's going to come in below me and I'm not going to get this job, which means that I'm not going to eat, which means that I'm going to have to go back to working full time, which is the bane of my existence. So the stakes are very high for freelancers, and it comes to a pinnacle moment every time you're pitching a client.\n\nCole Heilborn (00:12:31): Oh, interesting. There's a decisive point where everything comes to a head and you have to figure out how to get through that.", "token_estimate": 530, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:10:31", "end_timestamp": "00:12:31", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "68c0eda6-f3f7-4cf6-b4c0-b2dc9b8c57c8", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 8, "content": "Justine Mulliez (00:12:39): Yeah, I would say that the pitching process, especially as you're starting to place your rate or talk about money, I think that's where the wave of the money stories just collides into you. And that's why I think there needs to be a lot of work done around money stories before you get to the pitching process so that you feel prepared and you have the tools ready to use the scripts that you've practiced, the different ways of maneuvering through that conversation so that you feel like you're grounded in your worth.\n\nCole Heilborn (00:13:08): I see. So before you get to that point, before you worry about trying to set a rate, it's important to understand how you even view money because that will ultimately dictate how you set your rate or how you deal with negotiation. Is that right?\n\nJustine Mulliez (00:13:21): Totally, totally. I mean, if let's say that you are coming in with a perspective of like, oh, I have a big security blanket courtesy of my upbringing. I don't need to go high. Okay, well that might work for you today, but what about two years from now when you're still working with the same client, you haven't raised your rates and they're very, very comfortable with you completely undervaluing the work that you're doing. So in this one conversation, it might not matter two years from now it will, or similarly, you're coming in with scarcity, you're really scared of not being able to pay your bills. You might come in again lower just to guarantee yourself that work. And similarly, two years from now, can you actually make a living as a freelancer charging that rate? Probably not. So that's why I always encourage these kinds of thought processes and reflections happening way before, even as you're kind of in the process of ramping into your freelance business is a good time to start thinking about what is dictating my rate? Is it data? Is it story? Is it my story? Is it someone else's story? I think it just helps to come in with preparation.", "token_estimate": 502, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:12:39", "end_timestamp": "00:13:21", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "74db9c46-2da1-42ce-83af-102e579f0480", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 9, "content": "Cole Heilborn (00:14:31): So I think I'd love if you could share maybe an example if you're comfortable sharing your own personal story about your money narratives and now as you've started your business and been doing this for a while, is there an example of a narrative that you've had that you've had to adjust or think about differently?\n\nJustine Mulliez (00:14:47): Absolutely. I mean, when I was starting off freelancing, I had a little bit of a cushion that I'd saved up from working in college. And so I went in basically being like, I'm just going to, so I worked in events, and so my goal when I moved back to the ops, I'm French originally, so I was moving home. I basically was like, okay, I'm going to work for every single event that I can find and I'm going to do it for free. I show up and I do a lot of these things for free, and I'm a very hardworking person. So a lot of people were happy to have me on, but what that meant was I was setting the bar so low that each year, yes, I was getting paid, but then I'd find out that a colleague of mine who was an intern, I did local university, was making double what I was making. (00:15:29): So that was a huge impact, which is why I like to joke about helping freelancers not make the same mistakes I made or the fear around talking about money meant that I didn't sign a contract. I'm still waiting for 5,000 euro for one of my contracts. So that has entirely shaped that narrative. And then when I moved into coaching, it's a new industry, it's imposter syndrome. It's really the question, what value am I actually providing? So in my introductory calls and my discovery calls with new clients, I still have to mentally prepare myself to be like, okay, Justine, we're going to talk about money. We're going to get into the logistics of it. What you're doing is providing value. It's okay to ask to get paid for that. And so I'm still reworking some of those things in terms of my own notion of the privilege that I've had growing up and not letting that interfere with the value that I'm providing with the service that I'm providing now.", "token_estimate": 527, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:14:31", "end_timestamp": "00:14:47", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "4535e9d7-a02b-41a8-8cfc-019a7312b594", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 10, "content": "Cole Heilborn (00:16:22): I think I'm maybe seeing part of the gap that is a challenge for freelancers in a nine to five, whether it's accurate or not, someone else is typically defining your value as a freelancer, you get to do that yourself, and that can be really empowering. That can also be really scary and a giant mess of fear. And without someone, because you get to do it yourself, you have to figure that out. And when you're trying to find a job every day or every month, it's not like you get hired once in a nine to five and you're set for the next five years. You have to do this constantly in order to keep paying rent and keep feeding yourself, which I think can be really great because you learn to work on these skills and you can get better at 'em. But if it's something that's really truly a challenge, I mean, I find that to be a challenge. It doesn't always get better very quickly. I\n\nJustine Mulliez (00:17:21): Like that you're being honest. Yeah. These are still things like you've been in business how long?\n\nCole Heilborn (00:17:25): Almost seven", "token_estimate": 269, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:16:22", "end_timestamp": "00:17:25", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "0fa34d72-2c87-4e06-9edd-4e144c8a8500", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 11, "content": "Justine Mulliez (00:17:25): Years, right? Seven years. These are still things that we are learning over time because also the industry changes. And I think what you're saying is super valid because when we're applying for jobs and it's its whole own can of worms in terms of disparity across different groups, and yeah, we're just going to pause that for now, but it is true that when you're in the job market, you're seeing, okay, amount of experience required for this pay in this place. Again, the industries are completely changing now, but at least it gives you a range. So even if you don't apply for that job, you have a pretty good sense of applying for a different one. You can take that information and apply it In freelancing, so much of our industry is lacking transparency across the board that the experience that you're gaining from working with one client or from negotiating with one client, it's really hard to replicate. (00:18:19): It's hard to take that with you because you don't know why their budget is what it is. And so now you're going to go see a new company or a new brand or a new agency and try to advocate for yourself with, so the data, we're missing a lot of data because freelancers don't necessarily like to share their rates for their services. So we're missing data there. We're missing data from the companies themselves in terms of what their budget is, and then we're kind of missing a global understanding of how businesses function within this industry. So we're just constantly shooting in the dark, hoping something makes sense, and then you layer that on top of fear. And then on top of maybe other people's fear, the number of clients that I work with who tell me that their mentors are actually earning less than they are, and I am like, well, yeah, they might be really good at their craft, but they might be terrible at business. So again, it's like if you can't compare yourself to people doing the same thing as you and you can't understand the ecosystem, how do any of us get it? Right. It's so hard.\n\nCole Heilborn (00:19:22): Well, and I think that's the thing. There is no, right. That's kind of an arbitrary idea.", "token_estimate": 543, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:17:25", "end_timestamp": "00:19:22", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "354c8d12-1cec-4ad7-8c07-ad1feaada442", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 12, "content": "Justine Mulliez (00:19:27): Totally. And I know that I just launched us into this moment of despair. So the thing that I'd like for us to have more, so how do you do it? For example, what are some of the ways that you have figured out how to at least have a process that feels better than just shooting around randomly?\n\nCole Heilborn (00:19:45): So I think that answer has kind of evolved, and I think it's evolved as my own perspective of what my job actually is has changed. I think as I started out, I definitely felt like I was a freelancer. I was a hired gun. I would show up and for whether it's a hundred bucks or a thousand dollars, I would shoot your wedding. But as I've grown and I've been doing this, I think I don't really view myself as a freelancer anymore. I think of myself more as a producer or an entrepreneur. And so I'm managing a business and a team of people who are producing work. And so I think it's a little different just fighting a number and saying, this is my rate. I don't really operate off of an external rate. But if I think back to when I used to do that, yeah, I mean, I don't know what I did. (00:20:35): I didn't really have a process. It was more of like, well, what's your budget? Well, I would like to get paid this much. I don't have any other jobs, and so I need to be able to pay rent, so maybe this one job can cover all of my rent this month. I think as I started to become a little more in touch with folks in the industry, we started to talk a little bit more about rates. There's definitely, if you dig deep enough on the internet, you can find online articles and forums where people talk about rates. I think in the film industry, everyone who is a freelancer or contractor kind of looks at the union and makes a lot of decisions based off of them. And then you factor in your own skill level and your own location and how that affects your rates. So it's kind of this melting pot of different ways to find it. And I think for me back then it was just a combination of what do you do? What do you do? What do I feel like I should do? And that changes on a weekly basis sometimes.", "token_estimate": 533, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:19:27", "end_timestamp": "00:19:45", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "399d6c42-eedf-4b1e-b4da-1880fc37f077", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 13, "content": "Justine Mulliez (00:21:40): Totally. And I like the fact that you even brought in the reality because we're kind of talking about money is on more this global concept more conceptually, but really on the ground, so many freelancers forget about their cost of living. And I think the way that I like to kind of approach it with a lot of my clients and what we come to together, especially in the community coaching, is like, what does your lifestyle require of you to be able to make and what services do you have to offer and how often do you want to provide those services? And even just bringing it to basics is really helpful. And a lot of people are scared to do that because money is so scary because they don't want to check in with the reality of their financial situation, which I would say is probably the biggest thing that I work with clients on is just making money, this not taboo thing and just being okay with looking at your budgeting app or being okay with looking at your global expenses. There's a lot of avoidant tendency when it comes to money that I think is just even step one. It's like how to make money not scary. It's, it's a thing just like food. We need it to a certain extent and how can we take all the weight around, money away and just so that we can look at it for what it is, which is like a currency\n\nCole Heilborn (00:22:59): And is it taboo because of these stories that we tell ourselves?\n\nJustine Mulliez (00:23:04): I would say so. I would definitely say so. And because it's an adult topic, it's like it's kind of adulting and it's tedious. There's a lot of question marks, but how I like to frame it is like, okay, if we could just get everything on a piece of paper, then we know where our extremities are, we know what the picture looks like, but if we never get it all in one piece of paper, we're never going to, there's be so many question marks and what we're missing in data we make up in story. So what is all the data that we can have access to?", "token_estimate": 500, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:21:40", "end_timestamp": "00:23:04", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "810118dd-f996-4e3a-b329-3aa195828d7d", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 14, "content": "Cole Heilborn (00:23:40): So you're saying the more we can present our money, the idea of money and consolidate it and fully define it, the more control we have over it, rather than letting pieces of it kind of be scattered.\n\nJustine Mulliez (00:23:54): Totally. And I would also say, and knowing, okay, this is the real money and then these are my stories, and just even being familiar with your own perspective on money can be really helpful. You can look at it and be like, okay, through this perspective, I think I'm screwed. And from this perspective, I think there's hope. And maybe the one where there's hope, I have more opportunity to create change because if I constantly think I'm screwed, I might not take any action from that place. And so it's really figuring out what story gives me the most options.\n\nCole Heilborn (00:24:25): And so I'm imagining if you're in this situation, what you're suggesting is kind of realigning or readjusting your perspective so that rather than seeing your current month as a doom and gloom scenario, you look at it from another perspective and you start to see opportunities or strategies to work yourself out of that scenario.\n\nJustine Mulliez (00:24:45): Yeah, I mean, we talk about feast or famine as though it's this most well-known basic thing in freelancing. And I'm not saying that that doesn't exist. However, I will say that we could either say that we are at the mercy of feast or famine, or we can say that, okay, we grow. We can either farm leads or hunt leads or create leads. And so how do I help I reduce the extremity of this feast or famine, and how do I plan for my famines if I am noticing a trend? A lot of folks work seasonally in terms of they might be ski photographers or they might be mountain bike photographers, for example. And it's like, okay, great. So what is your game plan? What is your strategy for either lengthening your season or adding tools to your toolbox so that you can find different work? So it's just more how can I choose to fill the voids and what options do I have available at that point?", "token_estimate": 521, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:23:40", "end_timestamp": "00:24:45", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "a001c3ee-2182-47b0-b3e3-4b64b49d8a92", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 15, "content": "Cole Heilborn (00:25:49): Yeah, I like that example because I think that's an example that a lot of folks understand and can relate to, and we do kind of assume that it has to be reality or it is reality, but maybe in saying, well, feast or famine is reality that sets you up for failure, or it sets you up in a perspective that doesn't allow you to work out of that mindset.\n\nJustine Mulliez (00:26:11): And maybe the perspective is not like feast or famine is not true, but rather, okay, how do I prepare for the famine? How do I preemptively create opportunities where I think I might be hitting a famine? And I think that's way more empowering. You can take way more action from that place as opposed to being like, well, I'm just expecting famine.\n\nCole Heilborn (00:26:34): So everything that we've been discussing is kind of, well, it's all very negative. I feel like we often have a discomfort or an uncertainty with money. How do we reverse that thought? How do we go the other direction?", "token_estimate": 250, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:25:49", "end_timestamp": "00:26:34", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "9da15f8b-435b-4aee-8511-e8115e90bda2", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 16, "content": "Justine Mulliez (00:26:48): Yeah, I mean, I think obviously for me, the first step is even just awareness, just being aware of and actually defining what your current perspective around money is. So it's like maybe it's, I'm not worth money, or maybe it's money is inconsistent, prepare for the worst. So say yes to every job. And I think really the first step is just being like, okay, what do I believe around money? What are all of my money beliefs and what do I notice about them? So I think that's the first step. And the second step is asking yourself, is this useful to me? In what way do I gain from this? And in what way has this cost me? And most of the time we find that things are actually incredibly costly because then you write out a list of all of the ways in which this one perspective has gotten in the way. (00:27:36): So then one of the easiest things to do is being like, okay, hypothetically what if I thought the complete opposite? Then what choices would I have available and what actions could I take from that place? And then the final thing for me is really about preparation. So what I like to do, and this is something I do with my clients a lot, is we've talked about saboteurs or inner critics I think in our last call, but it's like what ecosystem or landscape do my most insidious money stories come up? When am I not necessarily triggered, but when is this the biggest issue? Is it the pitching process? Is it negotiation? Is it marketing in general? Where does this money creep happen? And then just really preparing for that. So maybe it's coming up with scripts, maybe it's coming up with processes that help you feel in control. Maybe it's just once a week having a conversation with a different freelancer to build relationships and to hear about how they're relating to money. The transparency piece for me is really important. So that's kind of how I can picture the process going from I'm in the hole to, I'm aware that there's a hole. I'm aware that there's an alternative, I'm preparing for the alternative and I'm testing the alternative.", "token_estimate": 521, "speakers": ["Justine Mulliez"], "start_timestamp": "00:26:48", "end_timestamp": "00:26:48", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "0b986903-f4bf-472c-a1a8-4e36bd023b03", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 17, "content": "Cole Heilborn (00:28:56): And I guess maybe this is a time to throw out the idea that your narratives aren't necessarily bad. They could be very helpful. And I guess my coupon example, maybe that instills in me a sense of frugalness and being responsible with my money, but just because I don't have to live entirely that way, but maybe taking some of these ideas and reformatting them slightly or repositioning them slightly can actually be used as an asset. Because if your default tendency is to save money, that's not a bad thing, but it can inhibit you as you plan and try to grow.\n\nJustine Mulliez (00:29:35): Yeah, I love that you brought that up because it's kind of like any tool that we have exists for a reason. It's a muscle that we've strengthened. However, what we want to be able to offer ourselves is not a dependence on this one way of functioning. So being frugal and being savvy with money, brilliant. That is genius. And it's great when you have that as one of the options to put on the table as opposed to, that is the only card I know how to play, and that's the only relationship to money I have. So for me, it's more like, how can we add more tools to your toolbox? Because me, with my history, me wanting to be generous with my services and not necessarily want to charge ridiculous also helped me build my career. It also allowed me to do some free work or some cheaper work for nonprofit organizations that then lend in me a big client. That was awesome, and I needed to also be able to advocate for myself and get paid when the situation called for it. So it very much as you're pointing out, is more of a yes. And it's like, okay, you believe that money's really important. Great. And can you also believe that that money can come back? So if you lose money this time around, you might make money later. It's more just expanding the relationship to money instead of only having one relationship to money.", "token_estimate": 484, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:28:56", "end_timestamp": "00:29:35", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "bbf30929-9e49-4458-a052-f6467814b524", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 18, "content": "Cole Heilborn (00:31:04): Right. Yeah. So you mentioned that oftentimes there's moments when our relationship with money is tested or it's really kind of on the front lines. What are some of those moments that you find that are common amongst freelancers? I'm assuming there's quite a few in the sales process, if there's any sort of change order or scope creep throughout the process, and then obviously the whole invoicing and actually getting paid for your work. Is there anything else where we often have to deal with these narratives the most?", "token_estimate": 137, "speakers": ["Cole Heilborn"], "start_timestamp": "00:31:04", "end_timestamp": "00:31:04", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "74884c19-8826-4d54-9c99-74301d6d49a1", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 19, "content": "Justine Mulliez (00:31:40): I mean, I would say that those are problematic enough. No, I'm kidding. I mean in the sense that for me, those are really the big ones. The one where I see I do the most work with my clients is when they have an opportunity to work with somebody that they're really excited about, the values align beautifully and they don't know what to price it because the company or the organization is not telling them what their budget is, hashtag life of a freelancer. And so it's really, that becomes the debate. It's like, I'm scared of pricing too high. I make them go through the exercise of what they would normally price, what they should be pricing. And then it becomes the conversation around like, oh, but what if I come in too high, they're just going to ghost me, or they're just going to reject me, or they're going to be offended. (00:32:29): This is a big one. They're going to be offended that I have the audacity of asking to be paid X. And so it's really, in this standpoint, it's really about reminding them that this is a co-creation and a collaboration, and that money is a conversation. It's very rarely just outside of the store. It's a conversation. So that is the peak panic, the money, peak money panic, I would say. And then absolutely the scope creep, learning how to advocate for yourself when a client is asking for more revisions being done, and that wasn't included in the agreement or having to flex the boundary muscle. That's the big one, because then again, it comes into the fear of like, well, what if they kicked me off the project and et cetera? And then, yes, billing, somehow you've done all of the hard work to get it happening, and then somehow literally asking to get paid, we panic. So those are definitely the top three phases. And I would actually even say promotion and marketing sometimes comes into play because people are almost embarrassed at the fact that they're asking to get paid for something that they do because you don't ask to get paid on your social media when you work at corporate job.\n\nCole Heilborn (00:33:52): Interesting.", "token_estimate": 527, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:31:40", "end_timestamp": "00:33:52", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "e9fedc23-9c24-4bf1-b995-ab14a1abca18", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 20, "content": "Justine Mulliez (00:33:53): Yeah. Is there anything that you think from either personal experience or from what you've noticed that's missing, perhaps?\n\nCole Heilborn (00:34:02): I mean, yeah, I feel like all those examples are external client facing. I think we kind of touched on it, but I think there's a lot of times where it's internal where you are looking at your budget for the year, for the month, or we're almost to march and we've got to start paying taxes soon. And when you're faced with those realities, that can be really challenging. And that's when you really start to either be like, wow, I had a really good year, or, oh, I got to find some extra money to pay my taxes. I didn't put enough away. So I think those are good to consider as well.", "token_estimate": 191, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:33:53", "end_timestamp": "00:34:02", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "8f18fdc3-6f0e-4244-baca-5c07e6097d17", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 21, "content": "Justine Mulliez (00:34:36): Totally. Yeah. Thank you for bringing that in. A hundred percent. I mean, before we hopped onto the call, I was going over my numbers and I a hundred percent agree. I think, again, those avoidant tendencies when it comes to the reality of your financial situation. I think also there's a lot of panic around the accounting piece. I think that's a big one too, is we were having to learn something completely new that we are very infrequently taught in school or even with our parents. So I think that's another one is like, do I need an accountant for this and can I expense this or not? And what falls under that umbrella? I think that's another context. And then, oh, another one, raising your rates, especially if you work with clients on a regular yearly basis, for example. I know that that's quite an intimidating conversation to have too. (00:35:30): I'm trying to think if there's anything else in terms of the themes. No, I think those are definitely the key ones. As you were saying, client facing and kind of internally, I will say that especially for folks that are in the premise or in the span of their business where they're starting to grow, I think ethical payment practices becomes this other component of stress is like, I want to pay someone equitably. I want to have them earn a living wage. When can I bring somebody on and pay them that livable wage while my business is growing big enough? So I think also the hiring conversation is another big moment of stress when it comes to the financial piece, for sure.", "token_estimate": 391, "speakers": ["Justine Mulliez"], "start_timestamp": "00:34:36", "end_timestamp": "00:34:36", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "5a8a5ffc-2714-42cb-9220-e381457ecb13", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 22, "content": "Cole Heilborn (00:36:14): Yeah. Interesting. So I'm imagining a scenario where you are interacting with a client and let's use, I don't know, scope creep as an example, and they're asking for more revisions. You're like, oh, I really want to make this client happy, but also they've gone over their revision count per our agreements. How do you have that conversation? I think that's a conversation that as a freelancer ultimately you'll have frequently, and it's not something that's a one and done thing. And so it almost seems like you can kind of develop a formula. And I know we've talked about this developing scripts or ways to navigate those conversations that you can kind of plug and play and tweak depending on the situation. Is that a thing that people can consider?", "token_estimate": 195, "speakers": ["Cole Heilborn"], "start_timestamp": "00:36:14", "end_timestamp": "00:36:14", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "850b6a98-f9e9-4d8b-8ff7-8fc5ad4f2f4e", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 23, "content": "Justine Mulliez (00:37:01): Yeah, totally. I mean, so I think the first thing I would think about is in how do I want to frame this? I think there has to be intentionality in terms of how do I want to position this and for the best outcome, and I would assume that the best outcome that we could, and maybe let's take a step back, what is the preferred outcome here? Is it that they go through with the revision and they pay me or that they don't go through with the revision and that they're still happy with what's happening? So I think that would be the first question I would ask myself is what is my preferred outcome? And from there, I would probably take myself through, okay, what is the relationship that I have to this client up to this point, and how can I position this so that the project is more important than my needs or their needs? (00:37:45): I am going to frame this in terms of what's beneficial for the project and ensure that the two of us are sitting on the same side of the table and that the project is the thing that we're working towards. And I think that's kind of something that people talk about in negotiation, or maybe it's couples therapy, I'm not sure, but it's making sure that you are partners on this thing so that you're not oppositional, you're not setting it up as an oppositional conversation. And so I would probably be like, oh, thank you for your feedback or for this input, not for the sake of the project, but I know that when we first started this work together, this is what we were aiming for. We were aiming for X, we were aiming for Y, we were aiming for Z. With this in mind, here are two options because you've reached your number of, we could either do the revisions and with this payment or maintain it as is and perhaps tweak X, Y, and Z. And so again, we're framing the project as the ultimate goal and we're offering them solutions to the problem that we're basically telling them is a problem. I don't know if that's clear enough, but that's probably how I would, and then ask for a very specific deadline of a return point of view and maybe hop on a call if it needs to be worked out.", "token_estimate": 537, "speakers": ["Justine Mulliez"], "start_timestamp": "00:37:01", "end_timestamp": "00:37:01", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "abe18d0b-27ed-4e03-8257-7e57221b1c4d", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 24, "content": "Cole Heilborn (00:39:03): So that's a really interesting idea that I feel like pops up a lot. The idea that it's the client freelancer relationship is this battle, and ultimately the outcome is the project, and you're trying to serve the client while also defending yourself. But that perspective shift of, oh, maybe we're actually on the same side here and sure we need to have some mutual agreement between us, but ultimately the outcome is the project, and that's what we're working towards together. In fact, that was a scenario that I feel like I frequently face. And an example of something I was dealing with last week trying to handle a client situation, and my first thought was, gosh, who do they think they are? They can just do this or ask for this. They know what the agreement says, but after letting some time pass, I was like, you know what? I'm glad I didn't respond that way. That would've been a terrible way to respond. Let's think about this from, okay, again, we're partners. How do we work through this together and ultimately reach an outcome? So it is incredible. I think realizing just what a small perspective shift that that can create as you start to communicate through solutions.", "token_estimate": 303, "speakers": ["Cole Heilborn"], "start_timestamp": "00:39:03", "end_timestamp": "00:39:03", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "ae999e4f-aaa2-43f9-9715-c3f5641e6edd", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 25, "content": "Justine Mulliez (00:40:21): And I think that's really kind of what's key in this is choosing how to respond instead of your default reaction. Some people's default reaction is to cater to the client. Some people, it's a people pleasing thing. It's like, oh my God, I'm going to get fired. I will do whatever you want me to do. And some people it's like, absolutely not. How dare they? And both of those are perfectly natural reactions, and they might not ultimately get you to your ideal outcome. And so I think, yeah, it's really about choice. And I say this having, I think it also might vary a little bit in terms of the relationship to the projects. And so I think designers, maybe people, I could see it being different for a photographer for example, who turns in photos and imagery after the shoot as opposed to a designer who's getting revisions and feedback, regular feedback on revisions. But at the end of the day, they're human. And I would rely on your ability to nurture that relationship for the sake of the project rather than allow it to get oppositional. People aren't trying to screw people over all the time. I would just assume positive intentions unless they've shown you otherwise.\n\nCole Heilborn (00:41:36): So that's a scenario where you can respond with email, where you have time to compose yourself. Oftentimes these conversations happen in a phone call or face-to-face, and you don't have the chance to pull up your script and then respond half a day later. How do you handle these things when they're happening in real time?", "token_estimate": 389, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:40:21", "end_timestamp": "00:41:36", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "cb76db7a-ff9c-4f69-b7c8-e76bd2a3fe00", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 26, "content": "Justine Mulliez (00:41:56): And this is probably, if I could say I learned anything from my coaching training, it's what I'm hearing is I think we totally under utilize reflecting back what we're hearing and not moving straight into assumptions. So I think that's the best technique to a mirror what they're telling you. And also to buy yourself time to regulate maybe the physical responses that you might be experiencing, especially if you're in a high stress situation or if you feel emotional, which we all do. Our bodies are like, something's happening. So I think the best tool that I would ever recommend in stressful situations is what I'm hearing is X, Y, and Z, because it might be right and it might be wrong. And so I like to kind of be like, this is what I'm hearing. This is what our goal was, these are the solutions I can provide. And kind of continuing to look at it as like, this is you. I'm on the same side as you, or this is you, this is our project. I'm on the same side as you. And what choices do we have? Easier said than done, takes a lot of practice to calm ourselves down. (00:43:09): I'm assuming this has happened. What are some strategies that you've used?", "token_estimate": 297, "speakers": ["Justine Mulliez"], "start_timestamp": "00:41:56", "end_timestamp": "00:41:56", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "2c3ed962-269d-435b-aab0-b9749494fb86", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 27, "content": "Cole Heilborn (00:43:15): I think clarifying is a really great tool. I guess to use another example, a couple of weeks ago I was chatting with a potential new client and it was a great relationship. There was nothing that personally that was frustrating. We were talking about a goal for the project and we were trying to come up with a couple of solutions in the proposal to reach that goal. And I outlined some options and they came back and they said, well, what if we did this? And it was a little bit of a back and forth trying to find the way to move forwards. And ultimately what they were suggesting didn't feel like the right solution for the project. It didn't feel like the right path. It wasn't setting it up for success. And so my first response was, well, this is a silly idea. Why would we do this? (00:44:03): This doesn't make any sense. But again, after some time, I suggested to the individual, well, let's get on a phone call and just talk through this. I want to understand how you're feeling or what your concerns are. And I think that was a really important step that I've learned is maybe someone, something gets suggested in an email and maybe the tone or the intentions are completely different than how you're perceiving them, but just taking the step to jump on a call and say, Hey, I read your email. I'm not, could you explain to me what you're thinking, what your thoughts are here? And as I assumed in that conversation, I kind of learned their thoughts, I learned their concerns, and then once I understood the root of what they were proposing, I was able to say, okay, well, based on this, why don't we do this? And in that call, we reached an agreement to move forwards, and now we're working together. So I think that's a really important step, just not letting yourself get in the way and giving them the opportunity to explain themselves.", "token_estimate": 469, "speakers": ["Cole Heilborn"], "start_timestamp": "00:43:15", "end_timestamp": "00:43:15", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "c0d73609-736c-44e8-9cae-4b9c1ac33306", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 28, "content": "Justine Mulliez (00:45:07): Yeah, I love that. I think great skills to practice and leverage is curiosity. Even how two people define one word, it could be completely off. And especially when it comes to the success metrics of a project or a partnership, I think that's really important to get clear, very clear right off the bat, and I don't know if this is something that I used to do naturally before getting into coaching, and my partner says that he's convinced that I do this to everybody in every conversation, which is maybe true, but it's really, as you were saying, kind of like what are they trying to say under what they're saying? So they're trying to suggest X. Why would that be beneficial to them? Oh, well, maybe because it means that there's less front loading work and they're actually at capacity and X, Y, and Z. So it's kind of like what could be underlying what's being said? And again, maybe it's just how my brain works, but I think if you don't know, ask assumptions are, again, we're missing data, we're missing information. So we're filling with story, and oftentimes the stories are not super positive. We're resonant. And so yeah, clarifying.\n\nCole Heilborn (00:46:24): Well, I think I've heard this before, clients don't know what they want. And so oftentimes they'll prescribe a solution that isn't an actual solution, and it's the freelancer's job to correct that. And so oftentimes clients come in, they're like, I know exactly what I want. And sometimes that's great, but other times you have that gut feeling in the back of your mind where you're like, I don't think this is the right thing for these people. And that's where you start to get into the conversation of value and what are you actually providing? Because clients don't always know what they want. They don't know what the right path is forward, but sometimes they feel like they need to give you direction or they have to give you, they're the client, they need to know what they're doing.", "token_estimate": 498, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:45:07", "end_timestamp": "00:46:24", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "c521b22d-c1a8-46a8-9342-31d9bf3ecabe", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 29, "content": "Justine Mulliez (00:47:03): Totally. I think that's such a key point. I forget who, I think it might've been Lisa gel from Wiley Creatives. I think we were having a conversation around clients, and something that she brought up too is you need to know the actual person you're talking to in terms of what are their aspirations in this company? What are their struggles that they're facing with their team? Also, how can this project help them on an individual? And that's something worth knowing about too. And so in hearing what you're saying is also you're dealing with an individual, so are they posturing because their boss doesn't feel like they take enough initiative and you just having to be the freelancer that is going to be inized. So yeah, I think just remembering that we're all human and therefore we could have imperfect moments and we could have opportunities for connection is like they're a person. Yes, they might be the North face or Patagonia, but the person that you're working with is a person. So don't let the brand or the size of the project take away from the fact that there is somebody else sitting across from you too.\n\nCole Heilborn (00:48:08): Yeah. Do you recommend that people write scripts if this, then do this, and then you write out an entire explanation of how to respond in a scenario like this? I mean, is that too far?", "token_estimate": 340, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:47:03", "end_timestamp": "00:48:08", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "bf30a51a-4455-40fb-88b3-ddbe07918167", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 30, "content": "Justine Mulliez (00:48:23): I wouldn't say that's too far. I think that might actually be a good, so sometimes I assign that as a homework assignment. I assign a dialogue that the person has to work through because it's a great tool to take the fear away. First off, you're examining every outcome. So we play out what happens if they fire you, and ultimately it's typically like, well, it would suck and I would survive. Cool. Great script. So on one hand, I think it's actually a really great exercise to do on your own is work through giving yourself the language to address complicated and nuanced situations. I don't know necessarily if I would say that you should be funneling clients through a script the way that a salesperson on a phone would, but honestly do what it takes to feel prepared and comfortable. I think language is really key in order to, it requires a certain level of finesse that not all of us have on a phone or not all of us have in an impromptu meeting. So I think working some of that and massaging some of that ahead of time is always good. So no, I don't think it's taking it too far. I think for preparation it's great. And also a lot of real life doesn't work out that way, so it's probably best to have the fluidity to deal with what's coming up. But I mean, if you're having that call with a hard client and you need to offer them solutions, prep the solutions and prep potential questions that are going to come up as a result.\n\nCole Heilborn (00:49:49): Yeah, I'm looking at our notes here and trying to figure out what would be the most useful to spend the rest of our time chatting about, because I know we've got until nine. Is there anything on your end that you feel like we should direct to?\n\nJustine Mulliez (00:50:07): I don't know. I feel like we've gone through quite a bit already.", "token_estimate": 458, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "00:48:23", "end_timestamp": "00:50:07", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "a899eacf-5ee2-4aca-b529-730cd834eeec", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 31, "content": "Cole Heilborn (00:50:11): So I feel like what we've discussed so far have been a lot of different things. A lot of these ideas have been kind of abstract, and I think we've done a good job of trying to root these in actual moments, but I think as any freelancer can relate to, we might have a great idea or we might have, our money mindset is positioned well, but when it actually comes down to the conversation with the client about they're on the edge, they're about to sign the contract, you're about to get the deposit. So many times it comes down to this one moment where you feel like you have to perform at a hundred percent in order to land that job. And in the back of your mind you're like, I got to pay rent, I got to buy food. I got to probably buy a pair of skis or whatever. So I'm wondering if it would be helpful to just try to dive into that scenario and maybe you and I can just play with that and what if I played a client? What if you played a freelancer and we just set up a scenario and just kind of worked through it? And I'd love to see, maybe I'm a stingy client who doesn't have a budget or doesn't want to tell you my budget, and I'd love to see how we could work through that considering some of the things we've discussed so far. How's that sound?\n\nJustine Mulliez (00:51:21): That sounds great. And I'm already feeling the nerves, and now this is making me empathize with all of my clients. I role play with them all the time and I force them to, and now I'm like, oh my gosh, I'm the client or I'm pitching. Even if it's pretend, it's still ingrained in my body to be scared. Yeah, totally. Let's do it.\n\nCole Heilborn (00:51:42): Alright. Does that feel like a good scenario if I'm a client who doesn't want to talk about budget or isn't upfront about that or does that seem\n\nJustine Mulliez (00:51:51): Good? Yeah, totally. Yeah, absolutely.\n\nCole Heilborn (00:51:55): Alright, so I'm going to pretend that I found you on you. What's your profession?\n\nJustine Mulliez (00:52:01): Why don't we say, I am a photographer, let's go there. Okay.", "token_estimate": 519, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:50:11", "end_timestamp": "00:52:01", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "30e3bea0-8baa-4233-b6fc-84616b855e20", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 32, "content": "Cole Heilborn (00:52:07): Alright. So Justine, I saw the photos that you posted of your dog. They're beautiful. It looks like you're really experienced taking pictures of dogs. I'm actually creating a new business model where it's an Airbnb for dogs and people come too, but it's really geared for the dog. So we have all the amenities that a dog could want. We've got all different types of grass and different turf options, plenty of toys, all of that stuff. And we're building a website and we're really looking for someone who can capture some amazing photos that show our facilities and hopefully invite people what make it feel inviting for pets and their owners to come hang out. Would you be interested in taking some photos?\n\nJustine Mulliez (00:52:49): This is happening via Instagram dm, correct?\n\nCole Heilborn (00:52:51): Correct.\n\nJustine Mulliez (00:52:52): Great. I would probably respond something along the lines of, I'd be just as enthusiastic. Clearly you're a client that has done some of your homework, you're excited about your idea. You want to share that with me. So I would probably be like, oh my goodness, this is such a cool idea. I love the vision that you have for your project. I'd be thrilled to talk about what it could look like for me to come on as a photographer for your launch. This might be a very personal thing, but for me, when I think about professionalism, I would probably want to move it from Instagram. So I would probably suggest that they send me their email so that I can send them my client call booking link. Again, that's personal preference, so I would probably be like, oh, I'd love to meet for a 30 minute discovery call so we can talk more about what vision you have and what your budget looks like. I would mention budget right away so that you as my future client would know that this is a paid thing. So then I guess we're on email now. I've sent you my link. You have booked a call and we're now on the call. Or actually, no. I would probably send you a questionnaire to prepare for our call. Okay. (00:54:08): So you fill out the questionnaire and you leave. And when I put project budget, you leave that blank.", "token_estimate": 544, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:52:07", "end_timestamp": "00:52:52", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "1127ecdf-3059-4b8e-b3bd-fdaf1cc674b6", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 33, "content": "Cole Heilborn (00:54:15): Yes. I say unsure.\n\nJustine Mulliez (00:54:18): Unsure. Great. So I read that and I now know that I'm going to have to do some education or some conversation around budget. So we're going to pretend that we're now on the call. I guess maybe if you want to.\n\nCole Heilborn (00:54:33): Yeah. Well, hey Justine, thanks for getting back to us. Yeah. Like we said, we really loved your photography. We'd love to work something out. I know in your questionnaire you asked about budget. To be honest, we're really not sure. We've never done this before. We are just trying to get a feel for how much something like you might charge for this. We're trying to get a couple bids from other photographers to make a good decision.\n\nJustine Mulliez (00:54:58): Great. Cool. Absolutely. I totally understand that you're in the beginning stages of this. I'd be happy to walk you through the different packages that I offer for photography. So we could either look at it through, I feel like I'm almost narrating the call, but I'm kind of explaining my thought process. So my thought process, especially on photography is there's multiple variables. So some people charge day rate, some people it's about licensing photos. It's also about how the photos will be used. Kind of where I guess I'm taking this is I'm almost thinking about it in terms of weddings, which would be a set time and then a set amount of photos.\n\nCole Heilborn (00:55:41): Well, how about this? I mean, I think these are all the things that someone would be asking themselves in a client call. So why don't we just ask the client,\n\nJustine Mulliez (00:55:49): Okay. Bring it back to the client call. Great. So Cole, the way that I tend to look at my rates or at the packages that I offer is I like to think about it either in terms of hours on shoot, and then in terms of the number of photos that I make available to you and their use. How many days do you think that you would want us on site?", "token_estimate": 495, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:54:15", "end_timestamp": "00:55:49", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "668d9bb9-4df8-4a18-bd30-cbf5f8aba9fa", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 34, "content": "Cole Heilborn (00:56:13): Well, I guess I don't really know how long it would take to take photos, but we've got a few different properties. They're kind of scattered around. I think that they're all in the Colorado area, so I don't know how you deal with travel or anything, but I'm assuming it'd be like half a day per location. We have five places that we'd like you to take photos of. And then, I mean, it'd be great if we could just get all of the photos that you take or if you're cool just giving us the flash drive and we could take them from there. That would be awesome.\n\nJustine Mulliez (00:56:47): Totally. So it sounds like if I'm hearing you have five different locations and you're thinking about around a half day for each of those, the way that I like to do travel is that we would organize it so that you would move me from location to location. So then we can talk about what the travel budget as well as the hotel and the whole accommodation and travel package will look like. And then when it comes to photos, part of what makes me good at my job is the way that I edit and filter my photos. So unfortunately, I will not be able to just give you a flash drive for it. And while I understand that you might want all of the photos, I think it would probably be best for me to be really selective and to work with you in knowing exactly what kind of photos that you're looking for so that you are handed the perfect 200 images that you need that will serve you across social media, your content and your website. (00:57:44): However, if you're looking for any imagery that might be put on merchandise or used in some of these bigger things, that would also be an added cost just because of the use. So what I can suggest is I'm most likely, I typically charge a thousand a day with not including travel and accommodation, and then probably another thousand for the use of imagery. So that would be a total of about 5,000 for photography, not including the travel package. How does that land for you in terms of what your expectations were or the budget that you have for this project?", "token_estimate": 526, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "00:56:13", "end_timestamp": "00:56:47", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "ccd8b630-c43c-4e45-ae57-632fbf3cfbad", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 35, "content": "Cole Heilborn (00:58:21): Yeah. Well, to be honest, that seems a little high. $5,000 just for some photos to go on our website seems like a lot for us to spend, especially because we're a new business and we're putting a whole bunch of money into this new website and we're trying to be really careful with how we spend our money. I guess I am a little, I don't understand why if you're shooting the photos, why you can't just give them to us. I understand that maybe you want to work with us, but what you provide isn't good. I guess that's a little concerning. And if we're spending that much money, I'd want to make sure that we're getting what we want.", "token_estimate": 164, "speakers": ["Cole Heilborn"], "start_timestamp": "00:58:21", "end_timestamp": "00:58:21", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "70c942e5-cedc-4106-8520-ad256fbe4d3d", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 36, "content": "Justine Mulliez (00:59:01): Yeah, absolutely. I think you bring up some really valid concerns and I'll just walk through them. So if I'm hearing you, one of the first concerns obviously is budget. I absolutely understand that you're in the beginning phases of your business. However, especially in the world that we live in through social media and content and web images speak louder than words. More ever, you're competing against companies that are spending maybe double, if not triple the amount for marketing and you have an amazing product. So we really want to let that sing. So in terms of the value marketing and visual identity is probably the most important thing in bringing in the kinds of clients that you want paying for your services. So that's putting it into context, whereas, so that's kind of just the bigger context. I'll also say that the kinds of imagery that I can create can also take you through multiple seasons so it can adapt to your business model and you could reuse them for years on end because they're going to be timeless. (01:00:01): That's my style. So we're ensuring that it's not just 5,000 upfront, it's 5,000 covering you for the years that you have coming up and the campaigns that you're running in terms of the choice of photo. Not every single photo that we take is going to give you something new and something extra. And so we want to make sure that it's a curated collection of photos that serve you and your needs specifically in order to make sure that the photos are to your standard. You and I will have a really in-depth conversation following this call to make sure that I understand your overall marketing strategy. I understand your brand, I understand the values, and I understand the mission and vision that you have for the company moving forward to ensure that you have all of the images that will support that. And in terms of finding a photographer for this, you're totally right. You want to make sure that this is the right photographer for you. Photographer, I might not be it. I think I'm probably a great fit though, and I would highly encourage you to think about working together and ask around for sure. Make sure that you find someone that you're a hundred percent comfortable with.", "token_estimate": 564, "speakers": ["Justine Mulliez"], "start_timestamp": "00:59:01", "end_timestamp": "00:59:01", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "2a8d32a1-1202-4364-af75-29486b239c46", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 37, "content": "Cole Heilborn (01:01:07): Alright, see now I really want to hire you as a photographer, but I am not going to, or I'm going to continue to try to be the stingy client. I feel like that was, you addressed my concerns. Well, that all makes sense, Justine. 5,000 is still out of our budget. I think if anything, we can put together a thousand dollars. I will say though, that we offer within each of our suites for our dogs, there's lots of branded pieces of gear that both dogs and humans can use on their adventures. And so we have lots of great connections with folks at, I don't know, Patagonia, north Face. So assuming that this goes well, maybe there's some connections that we could introduce you to if you'd be interested in doing this project for less than your rate.\n\nJustine Mulliez (01:02:05): That's such a kind offer, especially in terms of being a source for referrals in the future. With that in mind, what I could propose if a thousand dollars is the utmost that we can go is I would actually encourage us to find two of the four locations that you're most excited about and see if we can build imagery that could potentially make it seem as though it's being located in your other locations. So if we're reducing the budget to a thousand, we can do two locations for my normal rate and ensure that you're getting the quality of photos that you're looking for. And in terms of these referrals, that would be so lovely. And I'm pretty confident that the work that I'm going to hand back to you is going to make you want to sing my praises anyway.\n\nCole Heilborn (01:02:54): Well, I think that sounds fair. Maybe let me run this by the rest of the team and get back to you. But I feel really good with this conversation with you, and I'm excited about what we might be able to produce together.\n\nJustine Mulliez (01:03:04): Awesome. Let's make this Airbnb thing as best as possible.\n\nCole Heilborn (01:03:10): Interesting. Okay. I feel like I learned some things there.\n\nJustine Mulliez (01:03:13): Yeah, what were your takeaways?", "token_estimate": 511, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:01:07", "end_timestamp": "01:03:13", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "f8f9b95a-a145-4ef8-8849-867753c74d78", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 38, "content": "Cole Heilborn (01:03:15): So I think as the stingy client, I realized that I didn't know how you worked. I didn't know how your process worked. And so without understanding how, I just assumed that I could show up or I had to show up and be like, okay, I want to get Justine to work as cheaply as possible and ultimately deliver the most for me. And so I think that was the first thing was that you did a good job of walking me through how you did your work and kind of the philosophy behind it. I think that made it a little more clear as to how our working relationship might go.\n\nJustine Mulliez (01:03:54): Yeah, cool. And I love that. It's great to hear that because I think, again, it could have been really easy for me to be offended and to be like, well, who does this client think they are? How dare they try to treat me like this? And if I go at it in the notion that it is also partially my responsibility to educate my client, then we're kind of meeting each other halfway and I'm blushing. I feel it in my body that this was stressful for me because it is, right? We're affirming boundaries. So I think choosing to give the client the benefit of the doubt is a really key piece. And that being said, you also don't have to work with clients that you don't want to. But what I also appreciated in also the roles being reversed and me in navigating with a client is, and I don't typically say this, but what I'm really seeing is in order for this to feel like a conversation, I really think that this should happen over the phone. And I do know some folks that like to have this part of the conversation happen over email, but I could imagine there being that drop off and borderline ghosting and seeing someone's breakdown of X, Y, and Z and not also feeling like they are putting in the care, the connection and the need of nurture that people have when it comes to separating themselves from their money. (01:05:22): We have to make a case for clients because we don't know what their financial situation is on the backend either. So it's like help the client make this decision with you.", "token_estimate": 526, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:03:15", "end_timestamp": "01:03:54", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "65c219a9-9a67-477b-b1c6-2b33bc18884c", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 39, "content": "Cole Heilborn (01:05:32): Yeah. Well, how do, you told me your rate via email was $5,000. I probably would've just ignored it or said, thanks, but we'll go another direction. But being that it was a conversation, it wasn't so much of an adversarial discussion so much as try to carefully feel each other out and make sure that this seems like a good choice.\n\nJustine Mulliez (01:05:56): Yeah, absolutely. And I will say also, this is why some people who are really good at their craft are not necessarily good at their business because some people expect their craft to speak for itself, which is a very, it's an understandable perspective to have. And yet as you're pointing out, if I'm not a photographer, I don't know the work that goes into it, how expensive the equipment is, the insurance that's required on that, how fast your computer needs to be to edit. I don't know all of these things. So help me understand your logic because we're businesses, we're both businesses, and so there's a middle ground that you can reach in terms of talking about it through the business lens. And I know a lot of people shy away from that because they feel like it's salesy. But I think it's about the reframe of I'm helping educate my client and I'm helping show the outcome of my work and the value of my work instead of like, I'm trying to sell this client my services.", "token_estimate": 342, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:05:32", "end_timestamp": "01:05:56", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "c3fa37d0-53ad-40da-81e8-5967dbcf2726", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 40, "content": "Cole Heilborn (01:06:55): I agree with that to an extent. I would say I don't think you have to validate everything that goes into your rate. If I'm the client, I don't have to, in my Airbnb for dogs example, I don't have to verify if I'm charging $500 a night, I don't have to break that down into every $5 increments and explain why I'm charging that to someone on the other end. I think as a freelancer as well, you don't to feel obligated to say, well, I have insurance. I have an office, I have equipment, and go through the laundry list. I think that makes you sound kind of, I don't know if desperate is the right word, but you're trying to find external reasons to validate your value. Something that I have heard and I've tried to practice is just setting a minimum level of engagement and saying, my minimum level of engagement is let's say $2,500, $5,000. And just say, it's my policy. And letting that speak for itself and not feeling like you need to say, well, you get all these things for 5,000. It's like, if you meet this level, then let's talk more. But if you don't, maybe we're not a good fit.\n\nJustine Mulliez (01:08:12): I haven't heard of that in that way in terms of the framing of minimum level of engagement. And I think that's so powerful. I am going to steal that for a lot of my client's homework. And because it is kind of brazen and bold and also really affirming of, I forget what model it was, but she's like, I don't get out of bed for less than 10,000 a day. And it also partially educates the client you should be expecting to. That is the level of caliber that I provide. And I totally agree with you in terms of, I find that some clients will on their invoices, be like this and this and this and this and this, and it's like, unfortunately, that also opens the door to nitpicking like, oh, well, what if we used, for example, it would be like, oh, what if we used a different sim card, not sim card, not photo card, whatever.\n\nCole Heilborn (01:09:11): SD card.", "token_estimate": 500, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:06:55", "end_timestamp": "01:09:11", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "561ee41f-4b23-48f8-9bed-07bb9cf0f466", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 41, "content": "Justine Mulliez (01:09:12): Yeah, SD card. So we definitely, yeah, I feel like it's like everything in business, it's a fine line. It's like how can you educate your client? And as you're totally right saying without having to justify your price, how do you show that you're going to create value without selling, giving them all of your secret sauce that makes you good at your, so it's absolutely, it's the dance.\n\nCole Heilborn (01:09:37): So you're kind of getting into the conversation about time and billing for time. Do you bill for time? Do you bill for the project? Do you bill by? How do you bill? Because that framework oftentimes sets up what sort of value or how you perceive your own value to the client. What are your thoughts around that?", "token_estimate": 189, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "01:09:12", "end_timestamp": "01:09:37", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "89538676-dbc9-4ac6-aca6-b033bd6c31ae", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 42, "content": "Justine Mulliez (01:09:59): Well, actually I want to answer the second part first, which is understanding that, I mean, it's like the seven Ps of business or something. When I did entrepreneurship, two will one or whatever in college, that was the thing that stuck out the most. But your price and is part of your positioning, your price is part of your reputation, it's part of your marketing, it's part of your brand. So really being intentional about what does my price represent? Does it put me where I want to be in this industry? Does it represent the kind of caliber of work that I'm actually providing? Does it represent the years of experience that I'm bringing to the table? And also, does it fit my ideal client? Because it might not. And that's something that I think about a lot in terms for me, I know coaches who started off around the same time as me who have exactly the same kind of training, but who are charging like a thousand dollars a session. (01:10:49): Well, their ideal client expects them to be charging that much because of where they sit in their industry. If I charge a thousand dollars a session, I would have no clients. That's just not the industry that I'm in. It's not the kind of client I want to work with. So I think that's an important piece to remember as well, is what does my price say about me? Because that's the danger also with being too cheap or putting your price too is people might assume that you're not even worth being paid. And then the second part about different forms of billing. Yeah, that's such a whole can of worms.", "token_estimate": 395, "speakers": ["Justine Mulliez"], "start_timestamp": "01:09:59", "end_timestamp": "01:09:59", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "66e98e51-9fd4-4031-98fb-7edc8592460b", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 43, "content": "Cole Heilborn (01:11:27): So we've been talking a little about billing. I guess we can't talk about billing without talking about pricing and how pricing affects your positioning, how to consider pricing different projects. And obviously different industries and different job functions have different industry ways of charging For film, it's very common to charge by a day rate, whereas maybe editors or publications maybe are charged by a word count or something like that. How do you handle the pricing conversation? And I guess is price even the right way to think about how much you're charging for what you're providing?\n\nJustine Mulliez (01:12:04): Well, I actually think that you have a lot to say on this subject because I remember you and I did clubhouse conversation on pricing and I loved how you framed a lot of it. So I would say in terms of price, the way that I look at price, and I can't tell if it was formed pre or post our conversation, but the way I look at price is also is like I would say no, to answer your question, I don't think price is the right way of either trying to sell it to or position it to our client or even interpret it on our end.", "token_estimate": 293, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:11:27", "end_timestamp": "01:12:04", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "f0eb7370-0e14-4165-8301-4d9352b2e656", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 44, "content": "Cole Heilborn (01:12:36): Yeah, well, I think so cost is cost, price and value I think can be considered the same thing, but they're not the same thing. In my mind, cost is, and I'm taking this from someone else, I did not come up with this, cost is your time and expenses. That's everything from gear to insurance to charging for Adobe Suite. That's how much it costs you to produce the project. So if you charge the cost and nothing else, you would cover your expenses for that day, but you wouldn't make any money off of it. The price is your cost plus your profit. So 15, 20, 40%, whatever you charge for your profit. So now you're covering your expenses and you're making a little bit of money on top of that. The value though, that completely negates the idea of cost and price. While those are things you need to understand in your budget to make sure that you're not losing money on something. If what I'm going to produce for a client is only going to cost me $500, but the value that I'm going to provide to them, let's say is $3,000, in my mind, I should be able to charge them that $3,000 even though it's only going to cost me $500. And so I think that's where you start to look at your work as not just a product, but it's a product that provides value. And what does that tool that you just created for the business do for that client,\n\nJustine Mulliez (01:14:26): And how do you calculate the value that you're producing for that client? The big", "token_estimate": 366, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:12:36", "end_timestamp": "01:14:26", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "996ad496-be5a-4cc4-8da1-90518ffab51c", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 45, "content": "Cole Heilborn (01:14:30): Question? Yeah, so I mean that's where this theory sounds great in practice, but in terms of actual application, it's tough to determine that because it's very hard to look at a client and say, oh, well, I'm going to take this photo for you and it's going to do this for you. And oftentimes the business doesn't even know what the value of what you're going to do for them is. I think a great way to start that understanding is just to ask questions. So I think back to the scenario that we were just role playing, if I was the freelancer, maybe I would've asked, well, what do you hope your first year of business revenue will be? And really understanding how will these photos be used and how heavy will these photos influence people's ability to go through the purchase process on the website? I think understanding the consumer and well, what does the consumer look for? (01:15:40): How valuable will these photos be in the audience's mind? And trying to understand some rough idea of the value that I'm creating for this company. That doesn't always work. I think unless if you're really, really experienced, I think it is very difficult to come up with a firm number and say, this photo is going to be worth a hundred thousand dollars. If you can do that, that would be awesome. But I don't know that you can. But I think having at least some sort of an idea of what I'm going to produce is going to provide this because then that allows you to at least be in a ballpark of, well, what is this actually going to do for the client rather than what is it going to cost me to produce?", "token_estimate": 404, "speakers": ["Cole Heilborn"], "start_timestamp": "01:14:30", "end_timestamp": "01:14:30", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "2a6435d8-db74-4a78-af9e-03e3c8c3dbda", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 46, "content": "Justine Mulliez (01:16:24): Yeah, we talked about that in the clubhouse conversation, but for me it's almost like this is the lens, right? It's like you could look at how you price through three of those lenses. And it sounds like for you, the value piece is really figuring is being able to empathize with your client and try to figure out what the role of the thing that you're creating will play in the vision that they have for the business. And I think that that's super, super important, especially when you're creating something that does not exist yet. I think for filmmakers and photographers and designers in particular, I think writers, they have a whole other set of challenges because a lot of that is more like pitching, and that's priced usually around word or length of feature. But I think for the folks that are in, there's nothing there. And I'm creating the thing to have an overall goal is a really important thing to remember because sometimes I feel like people are going into negotiations with their clients feeling like they're just taking their client's money and then that's it. And it's like, no, you have to lean into the fact that you are creating something of value. And if you cannot articulate what that is, ask your client to articulate what that is. (01:17:45): Totally. I think that's a big one. I'm going to spend more time thinking about that in particular because an aha to this right now.", "token_estimate": 357, "speakers": ["Justine Mulliez"], "start_timestamp": "01:16:24", "end_timestamp": "01:16:24", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "36dd08f3-135e-48c2-9254-36cea698f205", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 47, "content": "Cole Heilborn (01:17:53): And oftentimes clients do know what their budget is, and if you approach it in a friendly conversational, we're working towards the same goal manner, they will share what their budget is. Over the years, I've had my own journey of trying to decide, well, I, it's like, do you pull your gun first and say your price or do you wait until they say your price? And who wins by giving their budget first? I think that's a game that we all play. And I mean we just did that, but I think a lot of clients actually do know what their budget is if you ask them. And so I've found at first my idea was I'm going to tell my price first because I don't want them, I want to shut down any client who isn't worth my time. That sounds mean, but that's not how I would say it. (01:18:43): But I've realized now that it's best if I hold my tongue and I ask them, well, what is your budget? And I have found more often than not that people have more money than I would've charged for the project. And I'm like, oh, okay. I'm really glad I didn't say $500 because you have a thousand dollars. And had I said $500, maybe I would've left $500 on the table. Or maybe the client will be like, well, maybe this guy isn't a good, he's not the right fit because he's undervaluing this by $500 in our perspective. So I think there's ways that you can ask what is your budget? And sometimes you might not get an answer, but I think there's other ways to kind probe at that question to get a response that you can use to figure out what works best for the client.", "token_estimate": 390, "speakers": ["Cole Heilborn"], "start_timestamp": "01:17:53", "end_timestamp": "01:17:53", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "002df246-5bbb-44e3-bb56-55c68b1b125e", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 48, "content": "Justine Mulliez (01:19:24): And I will also say it's a lot of people allow the money conversation to be the last thing on their calendar. They let five conversations go before even breaching the subject, and you have just wasted so much of your time (01:19:42): And the clients and the clients. So I think it's really important for that to be something that people decide if they're a fit for really early on in the conversations and not being so afraid of it because it's going on a first date and finding out that the person that you're on a date with does or does not want children, and that's a make or break for you. You want to find that out date one, not date 59 when you're thinking about proposing. So it's just, I think that kind of comes with this notion of there will be more options, there will be more opportunity. And I think to almost full circle back to the notion of money narratives, it's like you have to believe that there's enough for everyone, including yourself, and that this client saying no to this client or this client and you deciding mutually that you're actually not going to work together leaves the room open for clients that are a good fit. I was kind of celebrating with a past client for a client that she just landed, and I was like, what are you learning? Because that's who I am, and I'm never going to stop coaching my past clients. So I'm like, what are you learning without fail? She's like that. Anytime I get rid of clients that don't serve me, I land a new client that does every single time. So it's okay to walk away, and it's okay to do that really early to save yourself and them a lot of time.", "token_estimate": 411, "speakers": ["Justine Mulliez"], "start_timestamp": "01:19:24", "end_timestamp": "01:19:24", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "9dc4ba06-abb2-4d1a-a243-28a1d867ada3", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 49, "content": "Cole Heilborn (01:21:06): Well, yeah, and I think that you have the power to choose the relationships that you end up in. And I think as a freelancer, you assume sometimes that you're just at the mercy of the wind and you take whatever you can because you got to make things work. And some seasons are like that for sure. But as this conversation has, I think alluded to, you do have a lot of control, at least over 50% of the engagement. The other 50 is the client and how you manage that other 50%, you can do it. You don't have to just wait for someone to show up and dangle a carrot in front of you and be like, well, do you want this job or not?\n\nJustine Mulliez (01:21:42): Yeah, absolutely. And it's a very nuanced thing. There are systems at play that benefit people over others, and there are things that are completely out of your control and there are opportunities that for some reason, you're never going to get. And we can either continue to lean into that perspective and be passive and kind of be hoping, as you're saying, for the carrot to drop, or you can go create clients and reach out to referrals or reach out to past clients or network. So I think for me, what I always try to leave my clients with is you have the possibility of living creatively in your business, not just in your craft, and thinking creatively and thinking and experimenting and playing and kind of being loose with it for until you get your bearings can be one of the most positive things you can do for your business.\n\nCole Heilborn (01:22:38): Well, Justine, this conversation could go on for a long time, is it's a never ending topic, and I wouldn't be surprised if we do this again at some point. But I want to thank you for your time, and I think this has been a really, it's been a fun conversation. First, I think it's also been a really interesting and educational conversation for folks. I think we all deal with this stuff. We're all on our own journey around these different ideas, and I think knowing that we all deal with this stuff as a freelancer, it is tough, but there are ways to work through it as is evident, I think, by what you've shared today.", "token_estimate": 540, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:21:06", "end_timestamp": "01:22:38", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "81eda8b1-aced-4a17-b095-fca2b03e1b2d", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 50, "content": "Justine Mulliez (01:23:14): Totally. Thank you. Well, it's always a pleasure to have these conversations and thank you so much for opening your platform and to use it in this way to help educate and inspire freelancers and creatives in Ry. And I think for me, kind of like the last thought I want to leave before everyone's like turn her off, is we're all human. So it's like remember that there is a person, a human that you are talking to, whether you're a client. So please treat your freelancers respectfully and don't ghost them. Just give 'em an answer. And if you're a freelancer, give the client the benefit of the doubt. Assume that they want to hear from you in terms of co-creating something powerful. And within freelancers, please share your rates. Oh my goodness, whether it's with only three people, but your homework assignment fellow freelancers right now is like share your rates with some of your friends who freelance to, I cannot tell you the number of times that I've had clients who have been told by people in their industry how much they're making. And this is something I do within my client communities. I have open conversations around how much people are charging, but information means less room for stories. So collect that data, and that's your homework assignment,\n\nCole Heilborn (01:24:28): Justine. If folks want to follow along with you or I don't know, hit you up for photography, for Airbnb, for dogs, where can people go to connect?\n\nJustine Mulliez (01:24:37): Yeah. Well, my whole portfolio of dog photography, no, I'm kidding. Well, actually, I have a lot of photos of my dog on Instagram. I'm not a good Instagrammer, but you can follow me at just a wild on Instagram. You can also reach out to me at hello@justwild.com or on my website@justwildthought.com. I'm in partnerships with a lot of amazing people these next coming months, so you can probably find me through different programs and courses that I'm putting together or work with me one-on-one, all of those grand ways of interacting. And please know I love it when people enter my ecosystem, even if it's asking questions. So feel free to reach out.", "token_estimate": 538, "speakers": ["Justine Mulliez", "Cole Heilborn"], "start_timestamp": "01:23:14", "end_timestamp": "01:24:37", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "be694729-a076-408d-b8e5-2e6445d22309", "episode_id": "5d4cadb8-73cb-4d47-a245-4375bd24db46", "cms_item_id": "68225dfc7bb476527f8c4887", "chunk_index": 51, "content": "Cole Heilborn (01:25:19): Awesome. Well, thanks Justine, again, I appreciate it, and I hope you have a great rest of your day.\n\nJustine Mulliez (01:25:23): Thank you, you too, Cole. Thanks again. See you.\n\nCole Heilborn (01:25:36): Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial, and film production company based in the Pacific Northwest.", "token_estimate": 200, "speakers": ["Cole Heilborn", "Justine Mulliez"], "start_timestamp": "01:25:19", "end_timestamp": "01:25:36", "podcast_index": 95, "episode_name": "Ep 95: Dealing With Money As A Freelancer | Justine Mulliez | Just a Wild Thought", "slug": "ep-95", "web_url": "https://www.portsidepro.com/podcast-feed/ep-95", "guest_name": null, "guest_title": null, "categories": [], "short_description": "Freelancer Month! This whole month, we'll be sharing episodes that are geared more towards freelancers and answering the top questions they may have.", "podcast_length": "44:117"}, {"id": "c1fde49a-a1e7-409b-8c2c-f07073c9ce7e", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 0, "content": "Cole Heilborn (00:03): And if you can't show that you've done something comparable or similar to a prospective job, chances are unless you have a really good relationship with the clients, it's going to be hard for them to hire you because they can't see what you've been able to do. And so I think there comes a point where you just have to build a portfolio of work that you want to do and however you can build that portfolio, I think that's what everyone has to figure out. Welcome to the Backcountry Marketing podcast. My name is Cole Hoborne and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with Emily Holland. She's a podcast strategist coach. She's the former producer of the Nature Untold Podcast, as well as the Stoke Cast. And Emily, I don't know if we've ever officially announced it, but you have also been helping me produce this show for the last four or five, maybe six months,\n\nEmily Holland (01:27): 17 years. I don't know. Time is irrelevant now. Yeah, it's been really fun working together. I think we started working together in September of 2021.\n\nCole Heilborn (01:38): That feels right. I think it was shortly after we connected on your episode. We started talking more and I was like, wow, look at all these things that Emily could be helping me with for this show. And so for folks who don't know, if you've noticed an increase in our efficiency as a show, you can probably thank Emily for that.\n\nEmily Holland (01:58): I don't know about that,", "token_estimate": 504, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "00:03", "end_timestamp": "01:58", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "7d9b1a3a-4422-43d6-9bf4-67656fdbc31f", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 1, "content": "Cole Heilborn (02:01): But I'm super excited to have this conversation. As folks know, we're in the middle of our freelance March month, and I just want to thank everyone who provided their feedback for us to try to find guests and find topics to discuss in this month. We got some awesome feedback from folks and we're really excited about the episodes and content that we have scheduled for this month. But as Emily and I were chatting about what do we want to do entirely with this month, there was a lot of feedback around topics about things that either we couldn't find guests for or they were really great ideas, but we weren't quite sure how to build out an entire topic or entire episode, rather. And so Emily thought, Hey, what if we just sat down and kind of riffed on some of these ideas and chatted through them? So Emily, I'll let you give us a quick introduction to yourself if you want, and then maybe run folks through what we're going to be discussing today.", "token_estimate": 244, "speakers": ["Cole Heilborn"], "start_timestamp": "02:01", "end_timestamp": "02:01", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "f6b79e03-491a-4f38-9e02-148171795778", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 2, "content": "Emily Holland (02:58): Yeah, thanks. So yeah, I'm a podcast strategist and consultant and coach, and I live in Boulder, Colorado. My pronouns are she and her and I have been working with podcasters both new and existing to essentially help them on their podcasting path. And that might be for a lot of folks, helping them just get more confident in their voice or in what they're putting out there in the world. And for some folks like yourself, cool, it's like, Hey, can you help me take things off my plate so things can run smoother and or give me time back in my day? So that's what I've been working on and on. I'm excited about this conversation because I think one of the things I've loved about working together with you is that I learned so much along the way, and you're a type of person that is good with that. (03:50): You're bringing people in who maybe don't have as much experience to some of your projects and saying, I think based on your skillset over here, you'd be a good fit for this. And so I've learned a lot from being pulled into things with you, and I think that there's a lot more that people listening can learn from you as well. So we're going to kind of run down some questions and just full send into it. I'm going to talk through some of your thoughts on answers and I can sort of add my 2 cents as someone who's a baby new self-employed person as well. First question, Cole, this is one of the hardest questions. I would assume that freelancers and creatives and self-employed people in general probably go through, which is how do you decide what to charge for your services as a freelancer or as a business owner?", "token_estimate": 412, "speakers": ["Emily Holland"], "start_timestamp": "02:58", "end_timestamp": "02:58", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "20060e8e-09c9-4e9d-8dda-afcf9d4c4e83", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 3, "content": "Cole Heilborn (04:45): Yeah, that's a great question. It's a hard one to answer. I think there's so many different variables and there's no one size fits all answer. I think a lot of it probably depends on your discipline and what sort of field you're in. Are you a creative, are you a photographer or are you a graphic designer? So I think that would be a good distinction to understand first. So I know I'm not answering your question, I'm more of just batting it back to you, and I got to be honest, answering the questions is a little weird. Usually I ask the questions on this show, so I'm going to do my best to actually give answers and not respond in questions. You're\n\nEmily Holland (05:23): Nailing it. You're nailing it so far. Well, let's just talk from the first when you first created your own agency, which you run Portside Productions, how did you think about pricing and what to charge? What was your mindset about that? First and foremost?", "token_estimate": 240, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "04:45", "end_timestamp": "05:23", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "db1d5970-c865-4e92-85e3-6a0ac2bc466f", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 4, "content": "Cole Heilborn (05:43): Sure. This probably will bleed a little bit into the conversation with Justine that came out. So if you want to deep dive into this, folks, I'd recommend you go check out Justine's episode. But to answer your question, I think when I first started, my main goal was to be able to buy food and pay rent. And so any amount of money that I could make that I could apply directly to my rent, that was my mindset. So I think at that point, I didn't really have any ideas about how do I make money? How do I price myself? The main goal was how can I survive through this month? So I think a lot of people start there, and I think a lot of people like myself probably didn't get into the freelance life because you wanted to be self-employed. You either had a camera or had a technical or creative skill, and you thought, well, I might as well try to head out there and see what I can do, or you just found some random jobs and the next thing you know you're filing for a business license and becoming a sole prop. (06:43): That was kind of my path, becoming my own boss, becoming self-employed was never a plan. It just kind of happens. And so I think a lot of people can probably find themselves in a similar situation as that, and at first it's like, I just need to make money. So that's how I started.\n\nEmily Holland (06:57): Yeah, I think that's really resonates with me as well. And I think it's also a little bit of a privileged position. I think we both were in where we're like, cool, we know that we probably have some safety nets if we need them, that we could fall back on. I could go live with my parents if I needed to, those types of things. But I think a lot of people are probably feeling similarly where they're just like, okay, baseline for the first six months, 12 months is just like, am I meeting my needs at the bare minimum, the things I need to actually survive? Not like buying new clothes, buying new gear that comes secondarily, right?", "token_estimate": 495, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "05:43", "end_timestamp": "06:57", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "18611f24-faf3-4eb2-8c5b-8902fa771fab", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 5, "content": "Cole Heilborn (07:36): Yeah, I think living as lean as you can is definitely a goal. And honestly, I was surprised with how little I could make and still live. You shop sales, you figure out a cheap place to live, and it's not by no means super glamorous, but if you're loving what you're doing for your job, for me at least, it made up for it. The thrill of trying to make it each month was enough to keep me going.\n\nEmily Holland (08:04): Yeah, for sure. I think the other maybe perspective from there too is there's some freelancers that they found themselves as a creative and they wanted to essentially just make money doing that, which is awesome. And then there might be more folks like me too that are coming from a corporate environment where all pricing that your company, whatever service or product your company is offering is set pricing. You have nothing to do with charging anything besides just like, this is what it is based on powers above me. So it's like a whole new concept to even think about what you yourself are going to charge. Because it's kind of like, and I know Justine talks about this too, is it's combined with you're selling yourself essentially as a service for a lot of these types of jobs. So it's a little bit of a weird mindset shift that has a lot to do with internal work you have to do.\n\nCole Heilborn (08:59): Totally. And I think, yeah, you realize, oh, if I don't go to work today or if I don't show up a hundred percent, then this is going to impact me tomorrow or next month. And you pretty quickly on realize everything relies on what I do today in order to make it, because you can't just expect something to show up for you. Sometimes that happens and those are great, but that doesn't happen all the time.\n\nEmily Holland (09:26): So maybe more tactically, let's talk about different types of ways that you can charge for your services. So I think you have some ideas around hourly versus day versus projects. So can you talk about the differences and maybe the pros and cons of each those?", "token_estimate": 510, "speakers": ["Cole Heilborn", "Emily Holland"], "start_timestamp": "07:36", "end_timestamp": "09:26", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "8ea19cde-0e49-4cdc-bdcc-ed4b8a80825f", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 6, "content": "Cole Heilborn (09:43): Yeah, so I think you hit on the main three buckets that I think about when considering how to charge. There's your typical hourly rates. There's the day rate, which is a little more common in the creative, specifically the film industry. And then there's project rate. And so I think they're all three, and I think every freelancer probably moves through charging three different ways for three different types of projects depending on where they are in their journey. I think hourly is a really easy place to start because you're like, I'm trading an hour of my time for an hour of my services and what I'm going to ultimately deliver this option is great because if there's any overages, if it takes longer to do the job, you're getting compensated for that. One of the biggest challenges of going freelance is quoting projects and calculating time and expenses. (10:40): And if you are off and you have to spend more time, but you're not getting paid more than you're making less money, or in the worst case scenario, are you actually losing money? So charging hourly is a great way to make sure that you're covering your time and you're being compensated. One of the downsides potentially to charging hourly though is that there's, and I'll say this, there's theoretically a limit with how much you could charge hourly if someone were to charge a thousand dollars an hour, people do. I think about attorneys, they charge ridiculous amounts of money per hour. But in the creative world, I think that's much less common, but there's kind of a cap on what you can charge hourly. And so as you get into bigger projects and as maybe your services start to evolve and you're offering more strategy or you're offering different types of value, sometimes hourly, I feel like you outgrow that and what you're providing no longer is best served in an hourly format. (11:41): Coming to the day rate idea, that's basically saying, okay, there's eight or 10 hours in a day, I'm going to charge X amount for all of this time, and this has a little more flexibility because sometimes you work half days, sometimes you work three quarter days, and depending on how you set up your rates and your contracts, you can get compensated accordingly. I think day rates makes a lot of sense. If in the film industry it makes a lot of sense because when you're on a production, you're not really thinking about it in the terms of hours, you're thinking about it in the terms of days. And so from a producer standpoint, it's much easier just to think, okay, I have this crew set aside for this amount of day rate per day, and you just kind of total it up in that way. I do think there's a component that a lot of the folks I work with when they work off of day rates as they have an additional gear charge, and that's something to consider as well, is I'm charging for my time, but I'm also charging for my gear. (12:37): And when I say gear, that can include obviously hardware, like cameras and lenses, but that can also include things like your internet and your software and more kind of soft expenses that you have, maybe reoccurring expenses that you have, and maybe you're not going to provide a line item that says Google Suite $15 a month, but those are the type of expenses that you should be considering when you're quoting for your time and however you decide to package that and present it to your client or employer or whoever. It's kind of up to you, but those are things to consider as well.", "token_estimate": 877, "speakers": ["Cole Heilborn"], "start_timestamp": "09:43", "end_timestamp": "09:43", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "d424339d-87d2-42aa-a5f2-eabcf98f4f76", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 7, "content": "Emily Holland (13:11): Wow, I really need to change my rate structure, I think based on that. That's awesome. So I think one thing that came to mind while you were talking is sort of this idea that's in the freelancing space and maybe more for writers than it is for video production or photographers, but could be both is sort of this idea that when you're first starting out, you should take any job so that you can build your portfolio regardless of how much it pays. And so I wanted to get your ideas on that kind of mindset and if you think it's a good way to go or if it's something that could be damaging, what are your thoughts on that?\n\nCole Heilborn (13:54): So is the question doing free work? Should you take free work,\n\nEmily Holland (13:58): Not free work, but really low pay work? That should probably be more, but you're new into the space, you're just trying to build up portfolio work.\n\nCole Heilborn (14:08): Got it. In this scenario, what am I providing? Am I a crew on a set or am I a graphic designer and I'm providing a logo? I'm not sure that it makes a difference, but I think\n\nEmily Holland (14:21): It could. Yeah, I think it may make more sense. Yeah, I think for writers, this is true that this sometimes happens to them. Graphic designers, probably true web designers, true coaches in general, like doing beta tests of maybe some of their group coaching programs and stuff like that. And then for you, maybe it's taking a production job that you're going to have to pay your crew their rates, but maybe you're not making enough or any at all in the beginning.", "token_estimate": 398, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "13:11", "end_timestamp": "14:21", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "695d2c2b-a7e5-4518-a603-dbb5d2739029", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 8, "content": "Cole Heilborn (14:53): Yeah. Yeah. This is a good question, and I feel like if you spend any time on a creative forum, there's going to be a lot of opinions. I think this comes down entirely to your experience and where you are kind of in the game. I say game because it feels like a game, but gosh, I guess to give a little background on how I've done this, I've done tons of free work and I've done tons of low paying jobs where either I lose money or whether I break even my accountant probably wouldn't advise that I keep doing those types of jobs, but I guess my idea is you have to start somewhere. And if you don't have a portfolio, because I believe that chances are you're not going to get hired for something that you haven't done before, and if you can't show that you've done something comparable or similar to a prospective job, chances are unless you have a really good relationship with the client, it's going to be hard for them to hire you because they can't see what you've been able to do. (16:02): I think there comes a point where you just have to build a portfolio of work that you want to do and however you can build that portfolio, I think that's what everyone has to figure out. It is funny, I was looking at my portfolio at our website and most of the projects on there are projects that we have either done at zero cost or have been done entirely for free, which I think is really interesting because most of our paid work is not on our website. And I think that's because I always try to put work out there that I want to get hired for, and more often than not, the things I'm getting paid for aren't always the things that I want to make more of. And I've had to find ways to build projects and make projects that I would like to do more of. (16:56): And so oftentimes that means just taking on a passion project and saying, you know what? I'm going to do this for free. Maybe this other project is going to fund this project or cover my expenses for this month, but I'm going to go out there and try to make it as best I can so that I have an excellent piece on my portfolio that I can then use to sell for the next project. But it comes down to your level of experience. If you're, you're a veteran freelancer and you're in demands and you have plenty of work that reflects the type of work that you want to do, chances are you don't need to do free work. If it's a really strong passion project though, and you believe in it and you have time for it and it feeds your soul, go for it. But if you're a new to the space and you're still trying to figure out where do you fit into the industry and you're trying to build that level of expertise and you don't quite have the portfolio yet, I think you kind of just got to get out there and start making stuff.", "token_estimate": 697, "speakers": ["Cole Heilborn"], "start_timestamp": "14:53", "end_timestamp": "14:53", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "6d8e7f44-119a-4e54-94d3-fc54fdc7c31c", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 9, "content": "Emily Holland (17:55): So if I'm tracking what you're saying, I think one of the really important things that you just said is that you essentially are like while you are taking jobs that maybe aren't in the exact direction that you want to go in, you're simultaneously taking action that will eventually push you in that direction. So as those contracts or projects or whatever kind of start to dissipate and go down, you can start pitching and focusing more energy on the one that you really want to go in. So reevaluating consistently, that's a really, I feel like powerful takeaway of that.\n\nCole Heilborn (18:27): Yeah, I think that's a great way to synthesize what I just said.\n\nEmily Holland (18:32): Tell me about why you should always be raising your rates and how you think about that.\n\nCole Heilborn (18:39): So I do think you should always be raising your rates. I guess the reason is if you don't, then eventually you might be five years down the road with the same clients who are paying you the same rate that they were five years ago, even though your value has increased significantly. And if you decide then one day to turn around and say, Hey, client who I've been working for five years, I'm raising my rate five times, that's probably not going to go over very well. So I think there kind of has to be a consistent increase over the right amount of time. I guess I'm not suggesting that maybe you do that every month or whatever, but I think it's a good practice to get into because ideally, the longer you do it, the better you get and the more you have to offer, and therefore your time should be compensated as such. What was the second part of your question?", "token_estimate": 421, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "17:55", "end_timestamp": "18:39", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "d2fa95ea-fab8-452d-8a1f-5a208022ae22", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 10, "content": "Emily Holland (19:33): I think you nailed it. Okay. I don't remember. Okay, cool. So that is something to just, I feel like one of the takeaways of consistent conversations around this freelancer month overall is that you have to constantly be evaluating. So you're constantly, every month, obviously being very aware of what's going out, what's coming in, are you managing your expenses? Are you paying your bills? Yes, be evaluating that, but also evaluating how much time and energy is this taking to do this type of work? Is it really the thing that I really want to do or do I want to focus on this type of work? So do you do that actively or is it just something that kind of happens in the back of your mind all the time that you're just reevaluating consistently?\n\nCole Heilborn (20:19): Yeah, I think it's kind of a continual thing. I guess my thought process is not with every project because I think that's too hard to maybe accomplish, but I'd say every year or every quarter, I want the types of projects we're doing and the types of clients that we're taking on to be generally bigger clients, bigger budgets with better creative. And so maybe if I'm looking at a year and I'm like, okay, did we achieve that from where we were in 2020 versus 2021? Did we move in that direction? If so, great. And maybe we took on a few projects that we're not in line with that ideal. That's okay. I think that's, you can't always expect to be growing the ladder or climbing the ladder every rung with a new client every time. But I think as a whole, that's been my approach is let's always be trying to find the best client and then once we find them, get into a really good spot with them and try to figure out how to continue to provide value to each other for the long haul.", "token_estimate": 445, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "19:33", "end_timestamp": "20:19", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "def41de4-c6da-4d20-87c3-ea174b6a2c9c", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 11, "content": "Emily Holland (21:28): Yeah, that's really good. So there's a couple questions within that. So you're talking about the good clients and sometimes you have clients that just don't align with the direction that you want to go. What has been your experience with essentially saying no to clients or potential clients or breaking up with clients that are not a good fit for you, for your mission, or for just what you're trying to do moving forward? I\n\nCole Heilborn (21:58): Mean, I think it's inevitable if you're growing and because we all start out with, I don't want to, there's no bad client because everyone along their own journey, it's the right client for them, but there reaches a point where the client that you're best suited for might not be the client that you have had for the last three years, and either they're not growing as you're growing or there's just a difference in values or opinions or eventually it's just not a good fit. And so in order for the best to the best to come to the client and for you, you sometimes have to make the decision, well, is this worth pursuing? And if it's not, how do I end this? And I think that kind of comes down to the relationship you have with the client and only you can kind of be the judge of that. (22:50): I think one way to slowly kind of I'll say weed your clients out is to be continually raising your rates. Eventually your clients will reach a point where they just, maybe they can't afford you and you're like, oh no, that's okay. No harm, no foul, but we're moving on or I'm moving on. But I don't think you have to be a jerk about it. I think you can provide alternative solutions. You can say, Hey, here's another person who's doing something similar. They're a few years behind me in terms of their progression, but they might be a better fit. I mean, the last thing you want to do is burn bridges or just be a bad person. But I think there's a lot of ways that you can be looking out for yourself and still be looking out for the client, even if that means you're not working together.", "token_estimate": 515, "speakers": ["Emily Holland", "Cole Heilborn"], "start_timestamp": "21:28", "end_timestamp": "21:58", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "e422df7b-0396-4670-b781-ff96d7c92e5c", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 12, "content": "Emily Holland (23:37): Yes. Okay. I like that you're saying you're looking out for the client's best interest and your interest if you're breaking up with them, because I think that almost might sound counterintuitive to some people when it comes to thinking about client relationships. So that I think is a really powerful takeaway. And so you kind of named a little bit, almost like from the backside, you were almost naming a couple of things that you do that maintain good relationships. But can you talk a little bit more about the things you actively do to have powerful client relationships that you can go back to for new projects or keep in touch with? What do you do to keep the client relationship as positive as possible and fruitful as possible too?", "token_estimate": 191, "speakers": ["Emily Holland"], "start_timestamp": "23:37", "end_timestamp": "23:37", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}, {"id": "65bcdd93-edcb-4ae6-9220-ed026b2069dc", "episode_id": "1cbbe421-6f09-45cb-947b-c33e54922c65", "cms_item_id": "68225dfc7bb476527f8c4889", "chunk_index": 13, "content": "Cole Heilborn (24:26): Sure. Yeah, that is a good question. I think this is one of those things that I'm always evaluating. So if we were just to dive into where my mindset is currently on that, I mean, I think from the beginning you should try to have a good idea of what is a good client and be able to define that so that when you start talking to a new lead or you start reaching out to folks trying to find jobs that you're reaching out to people who you think will be a good fit. And so that's aligning on things like values. Maybe it's aligning on even things like the industry. Are you in the automotive industry? Are you in the outdoor industry? Obviously aligning on the technical craft. If you're a photographer, are you talking to the graphic designer or are you talking to, actually maybe the graphic designer is in charge of photos, but simple things like that. (25:23): But I think beyond that, once you have found a good potential relationship, I think it really just comes down to obviously budget. Can they afford your services and does that feel fair? And then a big one is can you deliver and can you give them value so that they will want to continue to work with you, assuming everything else kind of checks out. So I think that's a really big area that it's a really obvious one. It's like we have to deliver on the things that we say we're going to do, but sometimes that's harder on some jobs than other jobs for whatever reason. So I think keeping that in the back of your pocket is like we always have to be doing. If we can ideally go above and beyond for every project, that would be awesome. And assuming those other things work out, that's probably going to be a client that you hopefully work with for however long.", "token_estimate": 437, "speakers": ["Cole Heilborn"], "start_timestamp": "24:26", "end_timestamp": "24:26", "podcast_index": 96, "episode_name": "Ep 96: Freelancing Q&A | Cole Heilborn & Emily Holland | Port Side Productions", "slug": "ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "web_url": "https://www.portsidepro.com/podcast-feed/ep-96-freelancing-q-a-cole-heilborn-emily-holland-port-side-productions", "guest_name": "Cole Heilborn", "guest_title": "Producer at Port Side Productions", "categories": ["creative"], "short_description": "Freelancer month continues with a special Q&A episode with your host, Cole Heilborn.", "podcast_length": "58:50"}]
